/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:({
  'news-stand':'Etymonline: https://www.etymonline.com/word/newsstand',
  'next to':'Etymonline: https://www.etymonline.com/word/next; https://www.etymonline.com/word/to',
  'night person':'Etymonline: https://www.etymonline.com/word/night; https://www.etymonline.com/word/person',
  'niner':'FAA Aeronautical Information Manual: https://www.faa.gov/air_traffic/publications/atpubs/fs_html/chap2_section_3.html',
  'nitinol':'NASA Technical Report: https://ntrs.nasa.gov/api/citations/20090019112/downloads/20090019112.pdf',
  'nevus':'Collins English Dictionary: https://www.collinsdictionary.com/us/dictionary/english/nevus',
  'nineties':'Etymonline: https://www.etymonline.com/word/ninety',
  'ninetieth':'Etymonline: https://www.etymonline.com/word/ninety',
  'ninthly':'Etymonline: https://www.etymonline.com/word/ninth',
  'no one':'Etymonline: https://www.etymonline.com/word/no; https://www.etymonline.com/word/one',
  'no matter':'Etymonline: https://www.etymonline.com/word/no; https://www.etymonline.com/word/matter',
  'no matter how':'Etymonline: https://www.etymonline.com/word/no; https://www.etymonline.com/word/matter; https://www.etymonline.com/word/how'
}[w]||('Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')))});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('neurotransmitter','Coined in 1959 from neuro- “nerve or nervous system” + transmitter; it names a chemical messenger that carries a signal between nerve cells.',C('neurotransmitter.s1','生物','When the signal reached the synapse, the neuron released a neurotransmitter that allowed the neighboring cell to respond.','信号到达突触时，神经元释放一种神经递质，使相邻细胞能够作出反应。','When the signal reached the synapse / the neuron released a neurotransmitter / that allowed the neighboring cell / to respond.','neurotransmitter 是神经细胞间传递信号的化学物质。','释放发生在突触处，作用对象是相邻细胞。'),M('The lab report called the electrical wire itself a neurotransmitter, although no chemical messenger crossed the synapse.','The lab report identified the chemical released at the synapse as a neurotransmitter.','电线传电流，不是神经细胞间传递信号的化学物质。'),[Q(1,'Where was the neurotransmitter released?','At the synapse.','Inside the computer battery.','On the outer surface of a bone.','神经递质在突触处释放。'),Q(1,'What did the neighboring cell do after the chemical signal arrived?','It responded.','It became a transmitter tower.','It stopped being a cell.','例句说明相邻细胞收到信号后作出反应。'),Q(1,'Which is an example of a neurotransmitter named in biology lessons?','Dopamine.','Cellulose paper.','Table salt alone.','Dopamine is a chemical messenger in the nervous system.','word-choice'),Q(1,'A neurotransmitter chiefly carries a signal between?','nerve cells','newspapers','muscle and bone as a physical wire','neuro- refers to the nervous system, and the term names its chemical messenger.')]);
P('neutral','From Latin neutralis “of neither side,” from neuter “neither”; meanings include impartial, chemically neither acid nor alkaline, and a gear position that transmits no drive.',[C('neutral.s1','政治','The mediator stayed neutral during the dispute and gave both neighbors the same time to explain their claims.','调解人在争端中保持中立，给两位邻居同样的时间陈述各自的主张。','The mediator stayed neutral / during the dispute / and gave both neighbors / the same time to explain their claims.','neutral.s1 表示不支持争端中的任何一方。','双方获得同等陈述机会，体现不偏袒。'),C('neutral.s2','科学','The chemist added an indicator to check whether the solution was neutral rather than acidic or alkaline.','化学家加入指示剂，检查溶液是否为中性，而不是酸性或碱性。','The chemist added an indicator / to check whether the solution was neutral / rather than acidic or alkaline.','neutral.s2 指酸碱性质既非酸也非碱；也可形容色彩不鲜艳。','酸性和碱性是化学中性的对立状态。'),C('neutral.s3','通用','Before the car was towed, the driver put the gear in neutral so the wheels could roll freely.','拖车前，司机把汽车挂入空挡，好让车轮自由滚动。','Before the car was towed / the driver put the gear in neutral / so the wheels could roll freely.','neutral.s3 作名词，指汽车变速器不向车轮传递驱动力的空挡位置。','汽车被拖动时空挡便于车轮转动。')],M('The mediator remained neutral by publicly endorsing one neighbor and refusing to hear the other.','The mediator remained neutral by hearing both neighbors before making a recommendation.','公开支持一方就不再是不偏不倚。'),[Q(1,'How did the mediator show a neutral position?','By hearing both neighbors equally.','By letting only one neighbor speak.','By refusing to attend the meeting.','neutral.s1 表示争端中不偏袒任何一方。'),Q(2,'A neutral solution is neither?','acidic nor alkaline','solid nor visible','hot nor cold in every case','neutral.s2 的化学义指既非酸性也非碱性。'),Q(3,'What does putting a car in neutral do?','It disengages drive so the wheels can roll.','It locks the wheels permanently.','It starts the engine automatically.','neutral.s3 指汽车空挡。'),Q(1,'Which sentence uses neutral to mean impartial?','The referee stayed neutral between the rivals.','The lemon juice was neutral at pH 2.','The car shifted into neutral.','此处 neutral 描述裁判不偏向任何竞争者。','context')]);
P('neutrality','From neutral + -ity, the noun formed from neutral; its central senses are impartiality between sides and the state of being chemically neither acid nor alkaline.',[C('neutrality.s1','通用','The small country declared its neutrality and promised not to join either side in the regional war.','这个小国宣布中立，并承诺不加入地区战争的任何一方。','The small country declared its neutrality / and promised / not to join either side / in the regional war.','neutrality.s1 指在战争或争端中不支持任何一方的状态。','承诺不加入任何一边即中立。'),C('neutrality.s2','科学','The technician measured the solution’s neutrality with a calibrated pH meter before the sample was stored.','技术员在保存样品前，用校准过的pH计测量溶液的中性状态。','The technician measured the solution’s neutrality / with a calibrated pH meter / before the sample was stored.','neutrality.s2 可指溶液既非酸性也非碱性的状态。','pH计用于判断酸碱状态。')],M('The treaty praised the country’s neutrality because it had sent troops to fight for one side.','The treaty praised the country’s neutrality because it had sent no troops to either side.','派兵为一方作战不符合战争中立。'),[Q(1,'What did the country promise under its neutrality policy?','Not to join either side in the war.','To supply weapons to one side.','To annex both neighboring countries.','neutrality.s1 指战争中不站队的立场。'),Q(2,'What did the pH meter assess?','Whether the solution was neither acidic nor alkaline.','Whether it contained a newspaper.','Whether it was politically independent.','neutrality.s2 描述化学上的中性状态。'),Q(1,'Neutrality is the noun related to which adjective?','neutral','neutron','newly','neutral + -ity forms the noun neutrality.','word-formation'),Q(1,'Which policy best demonstrates neutrality?','The mediator refuses to favor either party.','The mediator takes one party’s side.','The mediator leaves before hearing anyone.','不偏袒双方体现中立立场。')]);
P('neutralize','From neutral + -ize; it means to cancel an effect, make a substance chemically neutral, or make a territory neutral in a conflict.',[C('neutralize.s1','通用','The second dose was designed to neutralize the toxin before it could damage the patient’s organs.','第二剂药物旨在毒素损害患者器官之前将其作用中和。','The second dose was designed / to neutralize the toxin / before it could damage / the patient’s organs.','neutralize.s1 指抵消或消除某种作用。','药物阻止毒素造成影响。'),C('neutralize.s2','科学','A measured amount of base was added to neutralize the acid, bringing the solution close to pH seven.','加入定量的碱来中和酸，使溶液的pH接近七。','A measured amount of base was added / to neutralize the acid / bringing the solution / close to pH seven.','neutralize.s2 指通过化学反应使酸碱趋于中性。','加入碱使酸的酸性被中和。'),C('neutralize.s3','政治','The peace agreement proposed to neutralize the border zone so neither army could use it as a base.','和平协议提议使边境地带中立化，使两国军队都不能把它用作基地。','The peace agreement proposed / to neutralize the border zone / so neither army / could use it as a base.','neutralize.s3 指在战争中使地区成为中立区。','协议限制双方军队利用该区域。')],M('The chemist neutralized the acid by adding more acid until its pH fell further.','The chemist neutralized the acid by adding a measured amount of base.','继续加酸不会中和酸；中和需要与之反应的碱。'),[Q(1,'What was the second dose intended to do?','Cancel the toxin’s harmful effect.','Increase the toxin’s damage.','Turn the patient into a mediator.','neutralize.s1 表示消除不良影响。'),Q(2,'What was added to neutralize the acid?','A measured amount of base.','More acid.','An electric cable.','中和酸时加入碱。'),Q(3,'Why would a border zone be neutralized?','So neither army could use it as a base.','So one army could occupy it freely.','So it became an acidic laboratory.','neutralize.s3 指使区域中立化。'),Q(2,'Which pair can chemically neutralize each other?','An acid and a base.','Two identical labels.','A newspaper and a newsstand.','酸和碱可发生中和反应。','context')]);
P('neutron','Coined in 1921 from neutral + -on for an electrically uncharged particle in an atom; a neutron beam is a stream of such particles used in research or treatment.',[C('neutron.s1','物理','The isotope has six protons and seven neutrons, so its nucleus contains one more neutral particle than the common form.','这种同位素有六个质子和七个中子，因此其原子核比常见形式多一个不带电粒子。','The isotope has six protons and seven neutrons / so its nucleus contains / one more neutral particle / than the common form.','neutron.s1 指原子核中不带电的亚原子粒子。','中子与带正电的质子同处原子核。'),C('neutron.s2','科学','Researchers directed a neutron beam at the sample to study how its internal structure scattered the particles.','研究人员把中子束照向样品，研究其内部结构如何散射这些粒子。','Researchers directed a neutron beam / at the sample / to study how its internal structure / scattered the particles.','neutron.s2 指用于科学研究或医疗的中子流。','一束中子照射样品并发生散射。')],M('The report said a neutron has a positive electric charge identical to a proton’s.','The report said a neutron has no electric charge, unlike a proton.','中子不带电，带正电的是质子。'),[Q(1,'What electrical charge does a neutron have?','No charge.','A positive charge.','A negative charge.','neutron.s1 是不带电的粒子。'),Q(2,'What did researchers direct at the sample?','A stream of neutrons.','A single newspaper page.','A neutral mediator.','neutron beam 是中子流。'),Q(1,'Where is a neutron normally found in an atom?','In the nucleus.','In the outer paper coating.','In the car’s neutral gear.','中子是原子核中的粒子。'),Q(2,'A neutron beam is useful because it?','lets researchers study how a sample scatters neutrons','is a beam of neutral-colored light','contains no particles at all','中子束用于研究材料与中子的相互作用。','context')]);P('never','From Old English næfre, a compound of ne “not” + æfre “ever”; it means at no time, can strongly forbid an action, and can signal disbelief in informal speech.',[C('never.s1','通用','I have never seen the northern lights, although I have visited the region twice in winter.','我从未见过北极光，尽管冬天去过那个地区两次。','I have never seen the northern lights / although I have visited the region / twice in winter.','never.s1 常与完成时连用，表示到目前为止从未发生。','去过两次但没有见过，突出经历缺失。'),C('never.s2','通用','Never touch the glass panel while the warning light is flashing; it may be dangerously hot.','警示灯闪烁时千万不要碰玻璃面板；它可能烫得很危险。','Never touch the glass panel / while the warning light is flashing / it may be dangerously hot.','句首 Never 可用于强烈禁止或警告。','告示用 Never 明确禁止触碰。'),C('never.s3','口语','“They offered you the lead role?” “Never!” said Jo, laughing in disbelief.','“他们让你演主角？”“不会吧！”乔难以置信地笑着说。','“They offered you the lead role?” / “Never!” said Jo / laughing in disbelief.','never.s3 可在口语中作感叹词，表达惊讶或不相信。','说话者因难以置信而作出反应。')],M('I have never seen the exhibit before, but I visited it yesterday and again this morning.','I have seen the exhibit twice, once yesterday and once this morning.','两次参观与“从未看过”矛盾。'),[Q(1,'What does “I have never seen it” mean?','I have not seen it at any time.','I saw it every day.','I will see it tomorrow for certain.','never.s1 表示在任何时候都没有发生。'),Q(2,'What does the safety sign tell visitors?','Do not touch the hot panel.','Touch the panel whenever the light flashes.','Remove the warning light.','never.s2 用于强烈禁止。'),Q(3,'Why did Jo say “Never!”?','She was surprised and disbelieving.','She was confirming a scheduled appointment.','She was describing a neutral gear.','never.s3 在口语中表达惊讶。'),Q(1,'Which sentence correctly uses never with the present perfect?','He has never ridden a ferry.','He has never rode a ferry.','He never has ride a ferry.','完成时中用 has never + 过去分词 ridden。','grammar')]);
P('nevertheless','From Middle English never the less, later written as one word; it means “despite that” or “all the same,” linking a surprising result to a preceding difficulty.',C('nevertheless.s1','书面','The route was longer than expected; nevertheless, the hikers reached the cabin before sunset.','路线比预想的长；尽管如此，徒步者仍在日落前抵达小屋。','The route was longer than expected / nevertheless / the hikers reached the cabin / before sunset.','nevertheless 是连接副词，表示后句结果不因前述困难而改变。','路线较长本会拖慢行程，但他们仍按时到达。'),M('The road was closed; nevertheless, the driver turned back and never reached the village, so the report said the closure caused no delay.','The road was closed; nevertheless, the driver found a detour and reached the village on time.','nevertheless 引出与前述障碍相反的结果；原句却描述未能到达。'),[Q(1,'What happened despite the longer route?','The hikers reached the cabin before sunset.','The cabin disappeared.','The hikers abandoned the trip before starting.','nevertheless 引出意料之外但仍发生的结果。'),Q(1,'Which phrase is closest in meaning to nevertheless here?','even so','because of that','at the same time only','nevertheless 表示“尽管如此”。'),Q(1,'Which punctuation is suitable in the example?','A semicolon before nevertheless, then a comma after it.','No punctuation anywhere.','A comma between the subject and verb only.','连接两个独立分句时分号加 nevertheless 再加逗号是合适结构。','punctuation'),Q(1,'Why is nevertheless appropriate after “The route was longer”?','The hikers arrived on time despite the obstacle.','The route became shorter immediately.','The cabin was inside the hikers’ house.','后句结果与路线更长可能造成的延误形成让步关系。','context')]);
P('nevus','From Latin naevus “birthmark or mole”; the medical term names a congenital or acquired mark on the skin, often a mole.',C('nevus.s1','医学','The dermatologist photographed the nevus and measured it so any later change in shape could be compared.','皮肤科医生给这颗痣拍照并测量，以便日后比较形状是否变化。','The dermatologist photographed the nevus / and measured it / so any later change in shape / could be compared.','nevus 是医学术语，指先天或后天形成的皮肤色斑、痣。','医生记录皮损外观以便观察变化。'),M('The chart called the nevus a bone fracture and instructed the patient to avoid walking on it.','The chart described the nevus as a skin mark and recommended monitoring it for changes.','nevus 指皮肤上的痣或胎记，不是骨折。','word-choice'),[Q(1,'Which specialist examined the nevus?','A dermatologist.','A railway conductor.','A newspaper editor.','皮肤科医生负责检查皮肤上的痣。'),Q(1,'Why was the mark measured and photographed?','To compare it with any later changes.','To determine the patient’s shoe size.','To identify the paper used in the chart.','记录外观便于后续比较。'),Q(1,'A nevus is a mark on the?','skin','engine','newspaper press','nevus 指皮肤上的色斑或痣。'),Q(1,'Which description best fits a nevus?','A congenital or acquired skin mark.','A nerve signal chemical.','A type of neutral gear.','医学义是先天或后天形成的皮肤标记。','meaning')]);
P('new','From Old English neowe/niwe, from Proto-Germanic *neuja- and an Indo-European root meaning “new”; senses include recently made, unfamiliar, and replacing an earlier one.',[C('new.s1','通用','They moved into a new apartment with freshly painted walls and appliances that had never been used.','他们搬进一套新公寓，墙壁刚粉刷过，电器也从未使用过。','They moved into a new apartment / with freshly painted walls / and appliances / that had never been used.','new.s1 指最近制造、建成或购得，尚未使用的事物。','全新电器和刚刷的墙表示新公寓。'),C('new.s2','通用','As a new member of the orchestra, Lina learned the rehearsal routine from the other musicians.','作为乐团的新成员，莉娜向其他乐手学习排练流程。','As a new member of the orchestra / Lina learned the rehearsal routine / from the other musicians.','new.s2 指刚加入、对环境或活动还不熟悉。','她刚加入乐团，仍在了解流程。'),C('new.s3','通用','The council approved a new plan to replace the one that had failed during last year’s flood.','委员会批准了一项新计划，用来取代去年洪水期间失败的旧计划。','The council approved a new plan / to replace the one / that had failed / during last year’s flood.','new.s3 可指取代旧事物、与前一版本不同的另一项。','新计划将取代失败的旧计划。')],M('The appliance was brand new and had never been used, but the seller described it as second-hand and worn out.','The appliance was brand new and unused, so the seller described it as new.','全新未使用与二手磨损相矛盾。'),[Q(1,'Why were the appliances described as new?','They had never been used.','They had been repaired many times.','They were bought by the orchestra.','new.s1 指新制造或未使用。'),Q(2,'Why did Lina learn the rehearsal routine?','She had just joined the orchestra.','She had invented the old plan.','She was selling an apartment.','new.s2 指刚加入而不熟悉。'),Q(3,'What happened to the earlier flood plan?','It was replaced by a new plan.','It was repainted and kept unchanged.','It became a new orchestra member.','new.s3 可指取代旧方案的新版本。'),Q(1,'Which phrase means recently purchased but not previously owned?','a new bicycle','a new member','a new version of the rule','只有 new bicycle 明确用 new 表示新买/未使用的物品。','distinction')]);
P('newborn','A compound of new + born; as a noun it names an infant in the first hours or days of life, and as an adjective it means recently born or newly created.',[C('newborn.s1','通用','The nurse placed the newborn in a warm cot beside the mother and checked the baby’s breathing.','护士把新生儿放进母亲身边的温暖小床里，并检查宝宝的呼吸。','The nurse placed the newborn / in a warm cot / beside the mother / and checked the baby’s breathing.','newborn.s1 作名词，指刚出生不久的婴儿。','护士照料的是婴儿。'),C('newborn.s2','通用','A newborn research team was created to study how early sleep affects infant development.','一个新成立的研究团队开始研究早期睡眠如何影响婴儿发育。','A newborn research team / was created / to study how early sleep / affects infant development.','newborn.s2 作形容词可指刚成立或刚产生的事物。','团队是最近组建的，并非婴儿。')],M('The hospital labeled a ten-year-old visitor a newborn simply because she had arrived at the hospital that morning.','The hospital called the infant born that morning a newborn.','newborn 指刚出生的婴儿，不是刚到某地的任何人。','word-choice'),[Q(1,'Who was placed in the cot?','An infant in the first days of life.','A ten-year-old visitor.','A research laboratory.','newborn.s1 指刚出生的婴儿。'),Q(2,'What does newborn modify in “a newborn research team”?','A recently created team.','An infant sleeping in the team.','A team that has existed for centuries.','newborn.s2 可表示新成立的。'),Q(1,'Which care is especially relevant to a newborn?','Checking the baby’s breathing.','Repairing a newspaper press.','Changing the car’s gear to neutral.','新生儿需要由医护人员观察呼吸。','context'),Q(2,'The word newborn combines?','new + born','news + stand','neuter + neuron','newborn is transparently formed from new and born.','word-formation')]);
P('newcomer','From Old English niwe cumen “newly arrived,” later formed as new-come + the agent ending -er; it means someone recently arrived in a place, group, or activity.',C('newcomer.s1','社会','The neighborhood association paired each newcomer with a volunteer who could explain local services and bus routes.','社区协会为每位新来者安排一名志愿者，介绍当地服务和公交线路。','The neighborhood association paired each newcomer / with a volunteer / who could explain local services / and bus routes.','newcomer 指刚加入某个地方、群体或活动的人。','志愿者帮助新加入社区的人熟悉环境。'),M('The club welcomed a newcomer who had been its chairperson for twenty years and had never joined recently.','The club welcomed a newcomer who had just moved to the area.','长期担任主席并非刚加入的成员。','meaning'),[Q(1,'Who was paired with a volunteer?','A person new to the neighborhood.','A long-time chairperson.','A city bus route.','newcomer 指新到某地的人。'),Q(1,'What could the volunteer explain?','Local services and bus routes.','How to neutralize an acid.','How to print a newsreel.','例句给志愿者安排了介绍当地信息的任务。'),Q(1,'A newcomer to chess is someone who?','has recently started learning or playing chess','has played professionally for decades','has never entered a chess club or game','newcomer 可指刚开始某项活动的人。','meaning'),Q(1,'Which phrase is natural?','welcome a newcomer','newcomer since twenty years ago','newcomer of arrived yesterdayly','welcome a newcomer 是自然搭配。','collocation')]);
P('newly','From new + the adverb-forming suffix -ly; it means “only a short time ago” and commonly modifies a participle or adjective.',C('newly.s1','通用','The newly restored bridge reopened to pedestrians after engineers tested its supports and railings.','工程师测试桥梁支撑和栏杆后，这座新修复的桥重新向行人开放。','The newly restored bridge / reopened to pedestrians / after engineers tested / its supports and railings.','newly 是副词，表示某状态或动作最近才发生，常放在分词前。','newly 修饰 restored，说明修复刚完成。'),M('The bridge was newly restored in 1890, but the report says the restoration happened only last week.','The bridge was newly restored last week.','newly 表示最近发生，不能同时把时间说成一百多年前。'),[Q(1,'What does newly restored mean here?','Restored only a short time ago.','Never repaired at any time.','Scheduled to be restored next century.','newly 表示不久前完成。'),Q(1,'Which word does newly modify in the example?','restored','pedestrians','engineers','newly directly modifies the participle restored.','grammar'),Q(1,'When did the bridge reopen?','After its supports and railings were tested.','Before anyone inspected it.','Only after the bridge was demolished.','例句说明测试支撑和栏杆后重新开放。','context'),Q(1,'Choose the natural order.','a newly published report','a published newly report','newly a report published','newly 通常放在分词 published 前。','grammar')]);
P('news','From Middle English news, originally “new things,” a plural noun formed from new; it refers to recent information or a report/programme that presents it.',[C('news.s1','传媒','The news about the bridge closure reached residents through a text alert before they left home.','桥梁关闭的消息在人们出门前通过短信提醒传到居民那里。','The news about the bridge closure / reached residents / through a text alert / before they left home.','news.s1 指刚发生事件的消息或信息，形式上以-s结尾但通常不可数。','短信传达有关关闭的消息。'),C('news.s2','传媒','At six, the family watched the evening news to hear a broadcast report about the election results.','六点时，一家人收看晚间新闻节目，了解选举结果的广播报道。','At six / the family watched the evening news / to hear a broadcast report / about the election results.','news.s2 可指广播或电视新闻节目、报道。','evening news 是新闻节目。')],M('The news were delivered by a text alert, and each individual news were surprising.','The news was delivered by a text alert, and each piece of news was surprising.','news 通常作不可数单数；表示一条时说 a piece of news。','grammar'),[Q(1,'How did residents learn about the closure?','Through a text alert.','From a neutral gear.','By watching a newborn sleep.','news.s1 指关于新近事件的信息。'),Q(2,'What did the family watch at six?','A broadcast news programme.','A printed newsprint roll.','A live election meeting only.','news.s2 指新闻节目。'),Q(1,'Which sentence has correct agreement?','The news is surprising.','The news are surprising.','A news arrived yesterday.','news 通常作不可数单数，搭配 is。','grammar'),Q(1,'How can one item of news be counted?','a piece of news','a news','one newses','常用 a piece of news 表示一条消息。','countability')]);
P('news-stand','A compound of news + stand; it names a small kiosk or counter where newspapers and periodicals are sold.',C('news-stand.s1','媒体','Mara bought a city map and the morning paper from the news-stand beside the railway station entrance.','玛拉从火车站入口旁的书报亭买了一张城市地图和一份晨报。','Mara bought a city map and the morning paper / from the news-stand / beside the railway station entrance.','news-stand 指出售报纸、杂志等刊物的小亭或柜台。','地点是车站旁出售刊物的摊亭。'),M('The traveler bought a newspaper at a news-stand that sold no papers or magazines and served only hot meals.','The traveler bought a newspaper from the news-stand beside the station.','news-stand 的核心用途是售卖报刊，不是只卖热餐。'),[Q(1,'What did Mara buy at the news-stand?','A city map and the morning paper.','A newborn cot.','A neutral chemical solution.','news-stand 是购报地点。'),Q(1,'Where was the news-stand?','Beside the station entrance.','Inside the river.','At the center of the newspaper itself.','例句把摊亭放在火车站入口旁。'),Q(1,'What is typically sold at a news-stand?','Newspapers and magazines.','Neutrons and laboratory acids.','Only used cars.','news-stand 是报刊销售点。'),Q(1,'The compound news-stand combines news with?','stand','newborn','neutrality','词形由 news 和 stand 组成。','word-formation')]);
P('newscast','A modern compound of news + broadcast (with the shortened combining form -cast); it is a radio or television programme that reports current events.',C('newscast.s1','媒体','The local newscast opened with a report on the storm and then gave the latest road-closure information.','当地新闻广播先报道风暴，随后播报最新的道路封闭信息。','The local newscast opened / with a report on the storm / and then gave / the latest road-closure information.','newscast 指通过广播或电视播出的新闻节目。','节目连续播报风暴和道路信息。'),M('The station advertised a newscast but broadcast only instrumental music and no reports about current events.','The station’s newscast included reports about the storm and road closures.','没有新闻内容的音乐节目不是 newscast。'),[Q(1,'What did the local newscast report first?','The storm.','A neutral chemical reaction.','A new bridge opening ceremony only.','节目先播出风暴报道。'),Q(1,'A newscast is usually delivered through?','Radio or television.','A paper roll used in printing.','A station news-stand counter only.','newscast 指广播或电视新闻节目。'),Q(1,'What information followed the storm report?','Road-closure updates.','The actor’s moustache size.','A list of newborn names.','例句提到后续的道路封闭信息。'),Q(1,'Newscast is built from news and a shortened form of?','broadcast','newcomer','newborn','-cast is shortened from broadcast in the compound.','word-formation')]);
P('newsletter','From news + letter, attested in the 1670s; it is a short report sent regularly to members or readers, sometimes focused on a business or field.',[C('newsletter.s1','通用','The museum sends a monthly newsletter with upcoming talks, new exhibitions, and volunteer opportunities.','博物馆每月发送一份通讯，介绍即将举办的讲座、新展览和志愿者机会。','The museum sends a monthly newsletter / with upcoming talks / new exhibitions / and volunteer opportunities.','newsletter.s1 指定期寄送给群体成员的简短信息刊物。','博物馆按月向读者发送活动信息。'),C('newsletter.s2','通用','The engineering newsletter summarized recent safety rules and research findings for workers across the industry.','工程行业通讯为业内员工概述了近期安全规定和研究成果。','The engineering newsletter summarized / recent safety rules and research findings / for workers / across the industry.','newsletter.s2 可指企业或行业内部传递消息的刊物。','内容面向同一行业员工。')],M('The museum newsletter arrived every month but contained no updates, notices, or information for its readers.','The museum newsletter arrived monthly with information about its events and exhibitions.','newsletter 是传递消息的刊物，完全没有信息与其用途相悖。'),[Q(1,'How often does the museum send its newsletter?','Monthly.','Every ten years.','Only during a war.','例句直接说明按月发送。'),Q(1,'What information does it include?','Talks, exhibitions, and volunteer opportunities.','Only the price of the museum building.','A list of chemical elements without context.','newsletter 为读者提供近期活动消息。'),Q(2,'Who reads the engineering newsletter?','Workers across the industry.','Only newborn infants.','People buying maps at a station kiosk.','行业通讯面向业内员工。'),Q(1,'Which phrase is natural?','subscribe to a newsletter','subscribe a newsletter to','newsletter on monthly every','subscribe to a newsletter 是自然搭配。','collocation')]);
P('newspaper','From news + paper, recorded in the early 17th century; it names a printed publication of news and articles and, by extension, the company that produces it.',[C('newspaper.s1','传媒','He spread the newspaper across the table and read the front-page report while eating breakfast.','他把报纸摊在桌上，边吃早餐边读头版报道。','He spread the newspaper / across the table / and read the front-page report / while eating breakfast.','newspaper.s1 指刊有新闻、文章和广告的报纸。','头版报道属于报纸内容。'),C('newspaper.s2','传媒','The newspaper hired two reporters to cover the city council and the regional court.','这家报社聘请了两名记者，报道市议会和地区法院。','The newspaper hired two reporters / to cover the city council / and the regional court.','newspaper.s2 可转指出版报纸的报社或新闻机构。','报社能够雇用记者报道公共事件。')],M('The newspaper company hired reporters, but the sentence says the physical stack of printed pages signed their employment contracts.','The newspaper hired two reporters to cover the council and court.','雇佣记者的是报社机构义，不是纸张本身。','word-choice'),[Q(1,'What did the reader spread across the table?','A printed newspaper.','A chemical neutralizer.','A newborn blanket only.','newspaper.s1 指印刷报纸。'),Q(2,'What did the newspaper do in the second example?','It hired reporters.','It was read at breakfast as an object.','It closed the railway station.','newspaper.s2 指报社机构。'),Q(1,'Which newspaper sense is meant by “the newspaper was folded”?','The printed publication.','The company’s hiring department.','The city council.','可以折叠的是纸质报纸。'),Q(2,'Which sentence uses newspaper to mean the organization?','The newspaper assigned a reporter to the court.','She folded the newspaper into quarters.','Ink stained the newspaper page.','assigning a reporter is an action of the news organization.','distinction')]);
P('newsprint','A compound of news + print; it is the inexpensive paper stock, commonly made from wood pulp, used especially for printing newspapers.',C('newsprint.s1','媒体','The printer chose recycled newsprint for the community paper because the inexpensive stock was suitable for a large run.','印刷商为社区报选择再生新闻纸，因为这种便宜纸张适合大批量印刷。','The printer chose recycled newsprint / for the community paper / because the inexpensive stock / was suitable for a large run.','newsprint 指主要用于印报纸的廉价纸张，不是新闻内容本身。','大批量印刷采用低成本纸张。'),M('The warehouse stored newsprint as a list of current events rather than as rolls of paper for printing.','The warehouse stored rolls of newsprint for the newspaper press.','newsprint 是纸张材料，不是消息清单。','word-choice'),[Q(1,'Why did the printer choose recycled newsprint?','It was inexpensive and suited a large print run.','It was a radio programme.','It contained the latest election results.','newsprint 是适合大批量印刷的低价纸张。'),Q(1,'What does newsprint refer to?','Paper used especially for newspapers.','A journalist’s daily report.','A stand selling magazines.','newsprint 指印刷报纸所用纸张。'),Q(1,'What was stored in the warehouse?','Rolls of printing paper.','A live television newscast.','A group of new arrivals.','例句强调仓库里的纸材。'),Q(1,'Newsprint is made mainly for?','printing newspapers','broadcasting radio news','measuring a chemical’s neutrality','词中 print 指印刷用途。','word-formation')]);
P('newsreel','A compound of news + reel, coined in the early 20th century; it was a short filmed report of current events, commonly shown in cinemas before television news became widespread.',C('newsreel.s1','媒体','Before the feature film, the cinema showed a newsreel with brief footage of the flood and the relief effort.','正片开始前，电影院放映了一段新闻影片，包含洪水和救援工作的简短影像。','Before the feature film / the cinema showed a newsreel / with brief footage / of the flood and the relief effort.','newsreel 指以胶片呈现时事的短新闻影片，电视普及前常在影院放映。','电影院在正片前播放时事影像。'),M('The archive catalogued the silent paper bulletin as a newsreel even though it contained no film footage.','The archive catalogued the short filmed report as a newsreel.','newsreel 是影片，不是没有影像的纸质公告。'),[Q(1,'Where was the newsreel shown?','At the cinema before the feature film.','At a chemical laboratory.','Inside the newspaper ink cartridge.','例句说影院在正片前放映。'),Q(1,'What did the newsreel show?','Footage of the flood and relief effort.','Only a printed list of bus fares.','A fictional drama with no current events.','newsreel 呈现时事影像。'),Q(1,'A newsreel is best described as?','A short filmed report of current events.','A regular letter sent to members.','The paper used for printing a newspaper.','newsreel 是新闻影片。'),Q(1,'Why did newsreels become less common?','Television news became widespread.','Cinemas stopped showing any images.','Newspapers changed into neutral chemicals.','电视新闻普及后，影院新闻短片逐渐减少。','context')]);
P('newsstand','A compound of news + stand; it names a kiosk, stall, or shop counter where newspapers and magazines are sold.',C('newsstand.s1','媒体','The commuter stopped at the newsstand to buy a magazine before boarding the early train.','通勤者上早班列车前，在报刊亭停下买了一本杂志。','The commuter stopped / at the newsstand / to buy a magazine / before boarding the early train.','newsstand 指出售报纸和杂志的亭子、摊位或柜台。','杂志在报刊销售点购买。'),M('He bought a magazine at the newsstand, a place that sold no printed material and served only as a train platform.','He bought a magazine at the newsstand beside the station.','newsstand 是报刊销售处，不是站台。'),[Q(1,'What did the commuter buy?','A magazine.','A laboratory neutron.','A piece of newsprint as a souvenir only.','newsstand 是购买杂志的地方。'),Q(1,'When did the commuter stop there?','Before boarding the early train.','After the train had left yesterday.','While the train was underground.','例句说明上车前停下。'),Q(1,'What kind of place is a newsstand?','A stall or counter selling newspapers and magazines.','A studio broadcasting a newscast.','A press producing paper pulp.','newsstand 售卖报刊。'),Q(1,'Newsstand combines news with?','stand','born','reel','该复合词由 news 和 stand 构成。','word-formation')]);
P('newsworthy','A transparent compound of news + worthy; it means important or interesting enough to deserve coverage by journalists.',C('newsworthy.s1','媒体','The reporter judged the discovery newsworthy because it changed the town’s water policy and affected every household.','记者认为这项发现值得报道，因为它改变了镇上的供水政策，并影响每家每户。','The reporter judged the discovery newsworthy / because it changed the town’s water policy / and affected every household.','newsworthy 指值得新闻媒体报道的。','影响全镇供水并波及居民，使发现具有新闻价值。'),M('The editor called the routine filing newsworthy even though it contained no new, important, or interesting information.','The editor called the discovery newsworthy because it affected the whole town.','缺乏新意和重要性的信息通常不值得报道。'),[Q(1,'Why did the reporter consider the discovery newsworthy?','It affected every household and changed policy.','It was an ordinary form with no new information.','It was a chemical with no public relevance.','影响全镇居民的发现具有报道价值。'),Q(1,'Newsworthy most nearly means?','deserving news coverage','printed on newsprint','sold at a newsstand','newsworthy describes whether an event merits reporting.','distinction'),Q(1,'Which event is most likely newsworthy for a city paper?','A bridge collapse that closes the only route to a hospital.','One resident’s routine breakfast.','A blank sheet of paper.','重大且影响公众的事件更有报道价值。','context'),Q(1,'The suffix -worthy in newsworthy contributes the idea?','deserving or fit for','happening every night','made of paper','-worthy means deserving or suitable for the noun it follows.','word-formation')]);
P('next','From Old English niehsta, the superlative of neah “near”; it can mark the following item in time or order, the nearest place, what happens afterward, or the person/item to follow.',[C('next.s1','通用','Please read the next chapter before Thursday’s seminar so everyone can discuss the same section.','请在周四的研讨会前阅读下一章，这样大家就能讨论同一部分。','Please read the next chapter / before Thursday’s seminar / so everyone can discuss / the same section.','next.s1 作形容词表示时间或顺序上紧接当前项的下一个。','chapter 按顺序排在当前章节之后。'),C('next.s2','通用','The next house on the left belongs to the family that runs the small bakery.','左边紧挨着的下一栋房子属于经营那家小面包店的家庭。','The next house on the left / belongs to the family / that runs the small bakery.','next.s2 可表示空间上最近的、紧邻的。','按街道顺序，最近的一栋房子就在左边。'),C('next.s3','通用','We checked the map and next turned east at the stone bridge.','我们查看了地图，接着在石桥处向东转。','We checked the map / and next turned east / at the stone bridge.','next.s3 作副词可表示随后、接下来。','转向发生在查看地图之后。')],M('After finishing the first chapter, she said the next chapter was the one she had already completed before the first.','After finishing the first chapter, she began the next chapter in order.','next 表示顺序紧接其后，不是先于第一章。'),[Q(1,'What should the students read before the seminar?','The chapter immediately following the current one.','The final chapter of a different book only.','A newspaper sold at the station.','next.s1 指顺序中的下一章。'),Q(2,'Which house did the second example identify?','The nearest house on the left.','The farthest house across the country.','The house behind the reader’s current one in time.','next.s2 指空间上最近的房屋。'),Q(3,'When did they turn east?','After checking the map.','Before looking at the map.','At the same instant the bridge was built.','next.s3 表示随后发生。'),Q(4,'“Who is next?” asks for?','the person who should follow now','the person who came first yesterday','the nearest building','next.s4 可指下一个轮到的人。','meaning')]);
P('next to','A phrase formed from next + to; as a preposition it means beside or immediately adjacent to something.',C('next to.s1','语法','The first-aid kit is next to the red cabinet, not inside the locked drawer beneath it.','急救箱在红色柜子旁边，不在下面那个上锁的抽屉里。','The first-aid kit is next to the red cabinet / not inside the locked drawer / beneath it.','next to.s1 是介词短语，表示紧挨着、在旁边。','next to 引出与急救箱相邻的物体。'),M('The kit is next to the cabinet because it is stored inside a drawer several rooms away.','The kit is next to the cabinet and can be reached without opening the drawer.','在数个房间之外且放在抽屉内，不是紧挨柜子。'),[Q(1,'Where is the first-aid kit?','Beside the red cabinet.','Inside the drawer several rooms away.','On top of the roof.','next to 表示紧挨着。'),Q(1,'Does the instruction place the kit inside the drawer?','No; it is beside the cabinet.','Yes; next to always means inside.','Yes; the drawer is outside the building.','句子明确排除了抽屉里的位置。'),Q(1,'Which phrase means beside?','next to','next year','next chapter','next to 是表示相邻位置的介词短语。','distinction'),Q(1,'Choose the natural sentence.','The pharmacy is next to the station.','The pharmacy is next to at the station.','The pharmacy next the station is.','next to 后直接接地点名词。','grammar')]);
P('nibble','Recorded around 1500, perhaps from Low German nibbeln “to nibble, gnaw”; it means to eat by taking small bites.',C('nibble.s1','饮食','While waiting for the soup to cool, Asha nibbled a piece of bread instead of taking a full meal.','等汤凉下来时，阿莎小口咬着一块面包，没有吃一顿完整的饭。','While waiting for the soup to cool / Asha nibbled a piece of bread / instead of taking a full meal.','nibble 作动词，指一小口一小口地咬或吃。','少量咬面包与吃完整一餐形成对照。'),M('He nibbled the entire loaf in one bite without breaking or chewing it.','He nibbled the loaf by taking several small bites.','nibble 强调小口慢慢咬，不是一口吞下整条面包。'),[Q(1,'What did Asha do while the soup cooled?','She ate small bites of bread.','She swallowed a whole loaf at once.','She poured the soup onto the floor.','nibble 指小口咬食。'),Q(1,'Which action is a nibble?','Taking a tiny bite of an apple.','Eating a whole meal in one mouthful.','Refusing to touch any food.','小口咬苹果符合 nibble。'),Q(1,'Why did Asha choose bread in the example?','She was waiting for the soup to cool.','The bread was a newsreel.','She needed to neutralize the cabinet.','例句给出了等待汤冷却这一原因。','context'),Q(1,'Which sentence uses nibble correctly?','The rabbit nibbled the carrot slowly.','The rabbit nibbled the carrot in one unbroken swallow.','The rabbit nibble the carrot yesterday.','慢慢啃食与 nibble 的含义相符。','grammar')]);
P('nice','From Old French nice, from Latin nescius “ignorant, unaware”; its senses shifted over centuries from foolish to pleasant, kind, or precise and delicate.',[C('nice.s1','通用','We had a nice afternoon beside the lake, with clear skies and enough time for a quiet walk.','我们在湖边度过了愉快的下午，天气晴朗，也有足够时间悠闲散步。','We had a nice afternoon / beside the lake / with clear skies / and enough time for a quiet walk.','nice.s1 表示令人愉快、舒适或讨人喜欢。','晴朗天气和散步构成愉快体验。'),C('nice.s2','通用','The new neighbor was nice to the children and offered to help carry their boxes upstairs.','新邻居对孩子们很友好，还主动帮他们把箱子搬上楼。','The new neighbor was nice to the children / and offered to help / carry their boxes upstairs.','nice.s2 可形容对他人友善、和蔼。','主动帮忙体现友好。'),C('nice.s3','书面','Choosing the right shade required a nice distinction between two greens that looked almost identical.','要选对色调，必须细致地区分两种几乎相同的绿色。','Choosing the right shade / required a nice distinction / between two greens / that looked almost identical.','nice.s3 在较正式语境中可指精细、微妙或讲究的。','两种相近颜色之间的区别很细微。')],M('The neighbor was nice to the children by insulting them and refusing to help when they dropped their boxes.','The neighbor was nice to the children by helping carry their boxes upstairs.','侮辱和拒绝帮忙表现不友善。'),[Q(1,'How was the afternoon by the lake?','Pleasant and enjoyable.','Precise in a technical distinction only.','Unkind to the children.','nice.s1 表示愉快。'),Q(2,'Why was the neighbor described as nice?','The neighbor offered friendly help.','The neighbor insulted the children.','The neighbor refused to speak.','nice.s2 指友好和蔼。'),Q(3,'What did a nice distinction require?','Careful attention to a subtle difference.','A cheerful afternoon outdoors.','A new resident of the building.','nice.s3 可表示精细、微妙。'),Q(1,'Which use has the ordinary modern sense of “pleasant”?','We had a nice meal together.','The chemist made a nice distinction between two shades.','The treaty declared neutrality.','nice meal 使用常见的“愉快、不错”义。','distinction')]);
P('nicety','From nice + -ty; a nicety is a small but important point or a degree of exactness, especially in language, conduct, or careful work.',C('nicety.s1','通用','The translator checked the niceties of legal wording so that “may” did not become an unintended obligation.','译者仔细核对法律措辞的细微差别，避免把“可以”误改成意外的义务。','The translator checked the niceties / of legal wording / so that “may” did not become / an unintended obligation.','nicety 指细节、细微区别或对准确性的要求。','单个情态词的细节会改变法律效力。'),M('The editor ignored every wording detail, then claimed to have checked all the niceties of the contract.','The editor checked the niceties of the contract before approving its wording.','nicety 指需要细查的细节，不能说完全忽略细节却已核对。'),[Q(1,'What did the translator check?','Fine points in the legal wording.','The building’s nearest entrance.','The alloy’s nickel content only.','nicety 指措辞中的细微点。'),Q(1,'Why did the word “may” matter?','It could change permission into an obligation if mistranslated.','It named the translator’s niece.','It described the weather at night.','例句说明措辞细节会影响法律意义。'),Q(1,'A nicety is often?','a small but significant detail','a large printed newspaper','a five-cent coin','nicety 指细节或精确之处。'),Q(1,'Which phrase is natural?','observe the niceties of etiquette','observe a nicety to eat a sandwich','nicety of arrive soon','observe the niceties of etiquette 指遵守礼仪细节。','collocation')]);
P('niche','Via French niche “recess or kennel,” the word first named a shallow wall recess; figurative senses include a suitable role or a specialized market, with its deeper origin uncertain.',[C('niche.s1','通用','The sculptor placed a small bronze bird in a niche high in the gallery wall.','雕塑家把一只小铜鸟放进画廊高处墙壁的壁龛里。','The sculptor placed a small bronze bird / in a niche / high in the gallery wall.','niche.s1 指墙壁上的小凹处，可用于摆放雕像或装饰品。','小鸟雕像嵌在墙面凹处。'),C('niche.s2','通用','After trying several jobs, Omar found his niche in a workshop where he could repair old instruments.','尝试过几份工作后，奥马尔在一家能修理旧乐器的工坊里找到了适合自己的位置。','After trying several jobs / Omar found his niche / in a workshop / where he could repair old instruments.','niche.s2 比喻适合某人能力和兴趣的位置或工作。','修复乐器的工坊适合他的专长。'),C('niche.s3','通用','The small company built a niche market by making weatherproof bags for long-distance cyclists.','这家小公司为长途骑行者制作防风雨背包，从而建立了一个细分市场。','The small company built a niche market / by making weatherproof bags / for long-distance cyclists.','niche.s3 指规模较小、需求专门的细分市场。','产品针对骑行者的特定需求。')],M('The company entered a niche market by selling the same general product to every possible customer with no specialized focus.','The company entered a niche market by serving a small group of cyclists with a specific need.','niche market 面向特定细分需求，并非无差别地面向所有人。'),[Q(1,'Where was the bronze bird placed?','In a shallow recess in the wall.','On the roof of the gallery.','In a market stall outside town.','niche.s1 是墙上的壁龛。'),Q(2,'What did Omar find in the instrument workshop?','A role suited to his skills.','A tiny hollow for a statue.','A five-cent coin.','niche.s2 比喻适合个人的位置。'),Q(3,'Who was the company’s specialized market?','Long-distance cyclists needing weatherproof bags.','Every customer with no shared need.','Gallery visitors looking for bronze birds.','niche.s3 是针对骑行者需求的细分市场。'),Q(4,'To niche a product means to?','place or fit it in a suitable specialized position','damage it with a small cut','give it an informal name','niche.s4 可作动词，表示把某物安置在合适位置。','meaning')]);
P('nick','Of uncertain origin; the noun has meant a notch or small cut since Middle English, and the verb means to make such a small cut or mark.',[C('nick.s1','通用','A sharp edge left a tiny nick in the glass, but the crack did not spread across the window.','锋利的边缘在玻璃上留下一个小缺口，但裂纹没有蔓延到整扇窗户。','A sharp edge left a tiny nick / in the glass / but the crack did not spread / across the window.','nick.s1 指表面上的小缺口或皮肤上的小伤口。','玻璃上只有一处轻微缺损。'),C('nick.s2','通用','Be careful not to nick the painted frame while removing the old metal latch.','拆下旧金属插销时要小心，别把漆过的框架刮出缺口。','Be careful / not to nick the painted frame / while removing / the old metal latch.','nick.s2 作动词，指在表面刻出小缺口或擦伤。','拆插销时可能刮伤框架。')],M('The knife nicked the table, but it left no mark, cut, or indentation at all.','The knife nicked the table and left a small mark in the finish.','nick 作动词时会造成小缺口或刮痕。'),[Q(1,'What did the sharp edge leave in the glass?','A tiny notch or mark.','A deep hole through the wall.','A printed news report.','nick.s1 指小缺口。'),Q(2,'What should the worker avoid doing to the frame?','Making a small cut or scratch.','Putting it beside a cabinet.','Giving it a friendly name.','nick.s2 指造成小刮痕。'),Q(1,'Which injury could be called a nick?','A small cut on a finger.','A broken arm.','A burn covering the whole hand.','nick 可指皮肤上的小伤口。','meaning'),Q(2,'Choose the correct verb form: “She ___ the wood with the tool.”','nicked','nicksed','nickinged','nick 的过去式是 nicked，末尾辅音双写再加 -ed。','spelling')]);
P('nickel','Named in 1754 from Swedish kopparnickel, a shortened form of German Kupfernickel “copper goblin,” after ore that looked like copper but yielded none; it names the metal and a five-cent coin.',[C('nickel.s1','化学','The stainless-steel sample contains nickel, which helps make the alloy resistant to corrosion.','这块不锈钢样品含有镍，这种金属有助于提高合金的耐腐蚀性。','The stainless-steel sample contains nickel / which helps make the alloy / resistant to corrosion.','nickel.s1 指一种银白色金属元素，常用于合金。','镍被添加到合金中改善耐腐蚀性。'),C('nickel.s2','货币','The parking meter accepts a nickel, but the driver inserts two five-cent coins to cover the full fee.','停车计时器接受五分硬币，但司机投进两枚五分硬币才够全额费用。','The parking meter accepts a nickel / but the driver inserts two five-cent coins / to cover the full fee.','nickel.s2 在美国和加拿大可指面值五分的硬币。','句子明确把 nickel 解释为五分硬币。')],M('The coin collector labeled the metal sample a nickel coin and valued it at five cents even though it was a piece of alloy, not currency.','The coin collector called the five-cent coin a nickel and labeled the alloy sample as nickel metal.','要区分金属 nickel 与五分硬币 nickel。','confusable'),[Q(1,'Why is nickel added to some steel alloys?','It can improve resistance to corrosion.','It makes the steel into paper.','It gives the metal a positive charge.','nickel.s1 是用于合金的金属。'),Q(2,'What does one nickel coin represent in the example?','Five cents.','One dollar.','Five hundred cents.','nickel.s2 指美国或加拿大的五分硬币。'),Q(1,'What was the original “copper goblin” reference about?','Ore that looked like copper but yielded none.','A newsstand that sold copper coins.','A child’s nickname for a toy.','矿工以此称看似铜却不能提炼出铜的矿石。'),Q(2,'Which use names a coin?','She paid with a nickel.','The alloy contains nickel.','Nickel resists corrosion.','paid with 表明 nickel 是硬币义。','distinction')]);
P('nickname','From Middle English an ekename “an additional or familiar name”; redivision of “an ekename” produced “a nickname,” now an informal name used instead of or alongside a person’s real name.',[C('nickname.s1','社会','Her teammates used the nickname “Sparrow” because she was quick on the court and wore a bird-shaped pin.','队友们叫她“麻雀”，因为她在球场上动作敏捷，还戴着一枚鸟形胸针。','Her teammates used the nickname “Sparrow” / because she was quick on the court / and wore a bird-shaped pin.','nickname.s1 指朋友或群体使用的非正式称呼。','昵称与她的特点和胸针有关。'),C('nickname.s2','社会','The class nicknamed its new reading corner “The Nest” after the students built a wooden canopy.','学生们搭好木顶棚后，把班级的新阅读角起名叫“鸟巢”。','The class nicknamed its new reading corner “The Nest” / after the students built / a wooden canopy.','nickname.s2 作动词，表示给某人或某物起非正式名字。','主语 class 给阅读角取了名字。')],M('Her teammates used her formal passport number as a nickname, while insisting that it was an affectionate informal name.','Her teammates called her “Sparrow” as an informal nickname.','护照号码是正式标识，不是亲友间使用的非正式称呼。'),[Q(1,'Why did the teammates choose “Sparrow”?','She was quick and wore a bird-shaped pin.','She was a newsprint seller.','She had just joined the city council.','nickname.s1 是根据特点取的称呼。'),Q(2,'What did the class nickname the reading corner?','The Nest.','The Neutrality.','The Nickel.','nickname.s2 作动词表示给地点起名字。'),Q(1,'A nickname is usually?','an informal name used by friends or a group','a legal identity number','the title of a newspaper company','nickname 是非正式称呼。'),Q(1,'Why is “an ekename” relevant to nickname’s history?','It meant an additional name and was redivided as “a nickname.”','It meant a newspaper kiosk.','It was the original name of nickel metal.','nickname 源自 an ekename 的重新切分。','word-formation')]);
P('nicotine','Named in the early 19th century from Jean Nicot, the French diplomat who introduced tobacco to the French court; nicotine is the addictive, poisonous chemical found in tobacco.',C('nicotine.s1','健康','The nurse explained that nicotine can make smoking addictive and discussed support for patients who wanted to quit.','护士解释尼古丁会使吸烟成瘾，并与想戒烟的患者讨论可获得的支持。','The nurse explained / that nicotine can make smoking addictive / and discussed support / for patients who wanted to quit.','nicotine 是烟草中的成瘾性化学物质。','护士把尼古丁与吸烟成瘾和戒烟支持联系起来。'),M('The leaflet claimed nicotine was a harmless vitamin that prevents dependence on tobacco.','The leaflet explained that nicotine is an addictive chemical in tobacco.','尼古丁可造成依赖，并非预防依赖的维生素。'),[Q(1,'What did the nurse explain about nicotine?','It can make smoking addictive.','It prevents all dependence.','It is a type of newsprint.','nicotine 是烟草中的成瘾性化学物质。'),Q(1,'What support did patients discuss?','Help for quitting smoking.','Help buying more tobacco.','Help finding a nightgown.','戒烟支持与想停止吸烟的患者相关。','context'),Q(1,'Nicotine is primarily associated with?','tobacco','steel alloys','printed paper','nicotine 是烟草中的化学物质。','meaning'),Q(1,'Which statement is medically responsible?','Nicotine is addictive, so stopping tobacco use may require support.','Nicotine is harmless and prevents dependence.','Nicotine is a substitute name for a five-cent coin.','尼古丁具有成瘾性，戒烟者可寻求支持。','word-choice')]);
P('niece','From Old French nece, from Latin neptia, related to neptis “granddaughter or niece”; it means the daughter of one’s sibling or of one’s spouse’s sibling.',[C('niece.s1','亲属','My niece brought her science project to our house so her aunt could help her rehearse the presentation.','我的侄女（外甥女）把科学项目带到我家，请姑姑（姨妈）帮她练习演讲。','My niece brought her science project / to our house / so her aunt could help her / rehearse the presentation.','niece.s1 指兄弟或姐妹的女儿。','说话者作为她的姨妈、姑妈或其他姑姨辈亲属。'),C('niece.s2','亲属','After the wedding, he began calling his wife’s niece his niece too, since she was the daughter of his spouse’s sister.','婚后，他也开始把妻子姐姐的女儿称作自己的侄女（外甥女）。','After the wedding / he began calling his wife’s niece his niece too / since she was the daughter / of his spouse’s sister.','niece.s2 也可指配偶一方兄弟姐妹的女儿。','她是妻子姐姐的女儿，因此属于姻亲侄女。')],M('My niece is the son of my sister, so I called him my niece when introducing him.','My niece is the daughter of my sister, so I introduced her as my niece.','niece 指女性亲属；兄弟姐妹的儿子是 nephew。','confusable'),[Q(1,'Whose daughter is a niece in the first sense?','A brother’s or sister’s daughter.','A parent’s sibling’s son.','A spouse’s parent.','niece.s1 指兄弟姐妹的女儿。'),Q(2,'Why did the man call his wife’s sister’s daughter his niece?','She is his spouse’s niece by marriage.','She is his sister’s son.','She is his mother’s sister.','niece.s2 也包括配偶兄弟姐妹的女儿。'),Q(1,'What is the male counterpart of niece?','nephew','neighbor','newcomer','nephew 指侄子或外甥。','confusable'),Q(1,'Which sentence is correct?','My niece is my brother’s daughter.','My niece is my brother’s son.','My niece is my sister’s father.','niece 指女性；男性对应 nephew。','grammar')]);
P('niggle','First recorded around 1590 with an uncertain origin, perhaps Scandinavian; as a verb it can mean to remain a small worry or to find fault with minor details.',[C('niggle.s1','通用','A small doubt continued to niggle at Priya after the inspection, although the engineer had found no serious fault.','检查结束后，一个小疑虑仍困扰着普里娅，尽管工程师没有发现严重问题。','A small doubt continued to niggle at Priya / after the inspection / although the engineer had found / no serious fault.','niggle.s1 指小问题持续困扰某人。','疑虑虽小却在检查后持续存在。'),C('niggle.s2','通用','Instead of approving the clear report, the reviewer niggled over a comma and two harmless formatting choices.','审稿人没有批准这份清楚的报告，而是对一个逗号和两处无关紧要的格式选择吹毛求疵。','Instead of approving the clear report / the reviewer niggled over a comma / and two harmless formatting choices.','niggle.s2 指花时间挑剔微不足道的细节。','逗号和格式都是不影响内容的小事。')],M('The reviewer niggled over major safety failures but carefully ignored every tiny, harmless detail.','The reviewer focused on serious safety failures rather than niggling over tiny details.','niggle over 表示纠缠于细枝末节，而不是优先处理重大问题。','meaning'),[Q(1,'What continued to niggle at Priya?','A small doubt.','A large newspaper.','A new research team.','niggle.s1 指持续困扰的小疑虑。'),Q(2,'What did the reviewer criticize?','A comma and minor formatting choices.','A dangerous structural failure only.','The fact that the report was clear.','niggle.s2 指吹毛求疵。'),Q(1,'If a worry niggles at you, it?','keeps bothering you a little','vanishes before you notice it','becomes a nickname','niggle 可描述持续的小烦恼。'),Q(2,'Which action is niggling?','Arguing at length over a harmless comma.','Correcting a dangerous bridge collapse.','Approving a report without reading it.','对无关紧要的逗号纠缠属于挑细节。','distinction')]);
P('night','From Old English niht, from Proto-Germanic *nahts and an ancient Indo-European word for night; it can mean the dark period or the evening period used for activities.',[C('night.s1','时间','The hikers reached the shelter before night, when the trail would become difficult to see.','徒步者在入夜前抵达避难所，因为天黑后山路会变得难以看清。','The hikers reached the shelter before night / when the trail / would become difficult to see.','night.s1 指天黑后、大多数人睡觉的时段。','天黑影响山路能见度。'),C('night.s2','生活','She works at the hospital during the day and attends a language class at night.','她白天在医院工作，晚上参加语言课。','She works at the hospital during the day / and attends a language class / at night.','night.s2 可指与白天工作时段相对的晚上活动时间。','语言课安排在晚间。')],M('They arrived at night while the sun was high overhead and the trail was in full daylight.','They arrived at night after sunset, when the trail was dark.','night 指日落后黑暗时段，不是太阳高照的白天。'),[Q(1,'Why did the hikers hurry to the shelter?','The trail would be hard to see after dark.','The night class had started.','They wanted to visit a newsstand.','night.s1 指黑暗时段，影响视线。'),Q(2,'When does she attend the language class?','In the evening.','At midday during her hospital shift.','At dawn before sunrise only.','night.s2 可指晚上的活动时段。'),Q(1,'Which word contrasts with night in the first sense?','day','newspaper','niche','night.s1 是一天中黑暗时段，与 day 相对。'),Q(2,'“We went out at night” most naturally means?','We went out during the evening.','We went out at noon.','We went out during the next week.','at night 指晚上外出。','meaning')]);
P('night person','A transparent compound of night + person; it describes someone who feels more alert or active at night than during the day.',C('night person.s1','心理','As a night person, Luis does his best writing after dinner and schedules early meetings only when necessary.','路易斯是夜型人，晚饭后写作效率最高，只有必要时才安排一大早的会议。','As a night person / Luis does his best writing after dinner / and schedules early meetings / only when necessary.','night person 指晚上更清醒、更有活力的人。','他晚间效率高，尽量避免早会。'),M('She called herself a night person because she feels most energetic at dawn and falls asleep as soon as evening begins.','She called herself a night person because she feels most energetic late in the evening.','夜型人通常晚上较清醒，不是清晨最活跃。','meaning'),[Q(1,'When does Luis do his best writing?','After dinner.','At dawn before sunrise only.','During the first hour of every meeting.','night person 通常在晚上更清醒。'),Q(1,'Why does Luis avoid early meetings?','He is more alert later in the day.','He works only at a newsstand.','He is afraid of all clocks.','夜型人晚上精力较好，清晨可能不便。','context'),Q(1,'A night person is most likely to?','feel energetic late in the evening','fall asleep immediately after sunset every day','work only in a nighttime newspaper shop','该词指晚上精神较好的人。','meaning'),Q(1,'Which person best fits the term?','Someone who concentrates best late at night.','Someone who is always most alert at sunrise.','Someone who sells newspapers outdoors.','夜间活跃符合 night person。','distinction')]);
P('nightfall','A compound of night + fall; it names the time in the evening when daylight fades and darkness begins.',C('nightfall.s1','自然','The field team packed its instruments before nightfall so they would not have to cross the marsh in darkness.','野外小组在日暮前收好仪器，避免摸黑穿过沼泽。','The field team packed its instruments / before nightfall / so they would not have to cross / the marsh in darkness.','nightfall 指傍晚天色变暗、夜晚开始的时刻。','日暮后穿越沼泽会更危险。'),M('They started the hike at nightfall at noon, when the sun was directly overhead and daylight had just begun.','They started the hike at nightfall in the evening as daylight faded.','正午不是傍晚入夜的时刻。','meaning'),[Q(1,'When did the team pack its instruments?','Before darkness began in the evening.','At noon in full sunlight.','After crossing the marsh at midnight.','nightfall 是夜晚开始、天色变暗的时刻。'),Q(1,'Why did they avoid crossing the marsh after nightfall?','They would be crossing in darkness.','The instruments became newspapers.','The water turned chemically neutral.','例句说明日落后沼泽难以安全通行。','context'),Q(1,'Nightfall is closest in meaning to?','dusk or the onset of darkness','midday','the first hour after sunrise','nightfall 指黄昏入夜。','meaning'),Q(1,'The word nightfall combines night with?','fall','new','full','它是 night + fall 的复合词。','word-formation')]);
P('nightgown','A compound of night + gown; it is a loose garment worn in bed, traditionally by women or girls.',C('nightgown.s1','家居','Mina packed a warm nightgown for the overnight hospital stay because the ward was kept cool.','米娜为住院过夜装了一件保暖睡裙，因为病房里比较凉。','Mina packed a warm nightgown / for the overnight hospital stay / because the ward / was kept cool.','nightgown 指睡觉时穿的宽松睡衣，常为长裙式。','住院过夜时穿的睡裙提供保暖。'),M('She put on a nightgown to attend a formal daytime meeting, explaining that it was protective equipment for surgery.','She put on a nightgown before going to bed.','nightgown 是睡觉穿的衣物，不是正式会议服或手术防护服。','context'),[Q(1,'Why did Mina pack a nightgown?','She was staying overnight in a cool ward.','She was attending a daytime press conference.','She was going to repair a car.','nightgown 是过夜睡衣。'),Q(1,'When is a nightgown normally worn?','In bed or before sleeping.','While printing a newspaper.','During a chemical experiment only.','nightgown 用于睡觉时穿。'),Q(1,'A nightgown is a kind of?','loose sleepwear','newspaper stand','nighttime broadcast','nightgown 是睡衣。','meaning'),Q(1,'Which phrase is natural?','put on a nightgown','wear a nightgown to neutralize acid','nightgown a station','put on a nightgown 是自然搭配。','collocation')]);
P('nightly','From night + the adverb/adjective suffix -ly, continuing Old English nihtlic; it means happening every night or done during the night.',C('nightly.s1','媒体','The observatory posts a nightly weather update so visitors can decide whether the sky will be clear enough for stargazing.','天文台每晚发布天气更新，方便游客判断天空是否晴朗、适合观星。','The observatory posts a nightly weather update / so visitors can decide / whether the sky will be clear enough / for stargazing.','nightly 可作形容词，表示每晚发布或发生；也可作副词表示在夜间。','更新按夜发布，帮助安排夜间观星。'),M('The observatory issued a nightly update once every five years, rather than each night.','The observatory issued a nightly update after each evening observation.','nightly 表示每晚发生，不是每隔几年一次。','meaning'),[Q(1,'How often does the observatory post its update?','Every night.','Once every five years.','Only at noon.','nightly 表示每晚。'),Q(1,'What does the update help visitors decide?','Whether conditions suit stargazing.','Whether to buy a five-cent coin.','Whether the museum is a newcomer.','例句说明天气信息用于决定是否观星。','context'),Q(1,'Which phrase uses nightly as an adjective?','a nightly report','report nightlys','a report nightlier','nightly 修饰名词 report。','grammar'),Q(1,'Which phrase uses nightly as an adverb?','The team works nightly.','The team works nightful.','The team nightly work yesterday.','nightly 可作副词修饰 works。','grammar')]);
P('nightmare','From Old English nihtmære, “night incubus,” combining night with mare, an evil spirit believed to oppress sleepers; today it means a frightening dream or a very distressing experience.',[C('nightmare.s1','心理','After watching the frightening film, the child had a nightmare about being lost in a dark forest.','看完恐怖电影后，孩子做了一个噩梦，梦见自己迷失在黑暗的森林里。','After watching the frightening film / the child had a nightmare / about being lost / in a dark forest.','nightmare.s1 指令人害怕或不愉快的梦。','梦境包含在黑森林中迷路的恐惧。'),C('nightmare.s2','通用','The delayed luggage and three cancelled connections made the family’s journey a logistical nightmare.','行李延误和三次航班衔接取消，让这家人的旅程变成一场安排上的噩梦。','The delayed luggage and three cancelled connections / made the family’s journey / a logistical nightmare.','nightmare.s2 比喻极其困难、令人痛苦的经历或局面。','多次延误使旅程非常糟糕。')],M('She described the peaceful, effortless trip as a nightmare even though nothing frightened or troubled her.','She described the trip with lost luggage and cancelled connections as a nightmare.','nightmare 的比喻义表示令人痛苦、困难的经历，而非轻松平静的旅行。'),[Q(1,'What frightened the child in the dream?','Being lost in a dark forest.','Finding a newsstand.','Joining a new orchestra.','nightmare.s1 指可怕的梦境。'),Q(2,'Why was the family’s journey a nightmare?','Luggage was delayed and connections were cancelled.','The family slept peacefully at home.','The weather was pleasant throughout.','nightmare.s2 比喻困难的真实经历。'),Q(1,'Which experience is a nightmare in the literal sense?','A frightening dream that wakes the sleeper.','A pleasant afternoon at the lake.','A routine daily weather update.','字面义是令人害怕的梦。'),Q(2,'“The permit process was a nightmare” means it was?','extremely difficult and frustrating','a pleasant dream during sleep','completed immediately with no trouble','nightmare.s2 可比喻令人痛苦的局面。','meaning')]);
P('nighttime','A compound of night + time; it names the part of the day when it is dark, especially the hours after evening and before morning.',C('nighttime.s1','自然','The desert cools quickly at nighttime, so campers bring an extra layer even in midsummer.','沙漠夜间降温很快，所以即使在盛夏，露营者也会多带一层衣物。','The desert cools quickly at nighttime / so campers bring an extra layer / even in midsummer.','nighttime 指一天中天黑的夜间时段。','夜间温度下降促使露营者添衣。'),M('The report described nighttime as the bright period just after sunrise, when the desert was warming in daylight.','The report described nighttime as the dark hours after sunset, when the desert cooled.','日出后的明亮时段属于白天，不是 nighttime。','distinction'),[Q(1,'When does the desert cool quickly?','During the dark hours.','At midday under the summer sun.','Only when a newspaper is printed.','nighttime 指夜间。'),Q(1,'Why do campers bring an extra layer?','The desert cools after dark.','The desert becomes a newsstand.','The forecast applies only to newborns.','夜间气温下降，需要增加衣物。','context'),Q(1,'Nighttime is the opposite of?','daytime','newcomer','neutrality','nighttime 指黑暗时段，与 daytime 相对。'),Q(1,'Which compound is formed from night + time?','nighttime','nightfallingness','nightful','nighttime 由 night 和 time 构成。','word-formation')]);
P('nil','From Latin nihil “nothing,” via French nil; in British sports results it denotes a score of zero, and more generally it can mean nothing at all.',[C('nil.s1','体育','The visitors scored three goals while the home team finished on nil, losing the match three–nil.','客队进了三球，主队则以零分结束比赛，以零比三落败。','The visitors scored three goals / while the home team finished on nil / losing the match / three–nil.','nil.s1 尤见于英式体育比分，表示零分。','three–nil 是三比零的比分。'),C('nil.s2','书面','The audit found nil evidence that the missing funds had been transferred to another account.','审计没有发现任何证据表明失踪资金转到了另一个账户。','The audit found nil evidence / that the missing funds / had been transferred / to another account.','nil.s2 可表示完全没有、丝毫没有。','nil evidence 表示没有证据。')],M('The scoreboard showed the visitors leading four–nil, but the announcer said both teams had scored four goals.','The scoreboard showed the visitors leading four–nil, with four goals to none.','four–nil 表示一方得四分、另一方零分，不是两队各四分。','meaning'),[Q(1,'What was the home team’s score?','Zero.','Three.','Four.','nil.s1 表示比分为零。'),Q(2,'What did the audit find about evidence?','None at all.','A large amount.','Evidence of a new match.','nil.s2 表示完全没有。'),Q(1,'A score of two–nil means?','one team scored two and the other scored zero','both teams scored two','the match had no goals from either team','nil is a score of zero.','meaning'),Q(2,'Which phrase uses nil to mean “nothing”?','The project made nil progress.','The team won by two–nil.','The player wore number nil.','nil progress means no progress at all.','distinction')]);
P('nimble','From Old English næmel “quick to grasp,” related to niman “take”; the unetymological -b- appeared later, and the adjective now means quick and light in movement or thought.',C('nimble.s1','体育','The nimble goalkeeper shifted left at the last second and caught the ball before it crossed the line.','敏捷的守门员在最后一刻向左移动，在球越过门线前把它接住了。','The nimble goalkeeper shifted left / at the last second / and caught the ball / before it crossed the line.','nimble 指动作轻快、灵活，也可形容思维敏捷。','守门员快速移动并接球。'),M('The nimble goalkeeper moved too slowly to reach the ball and remained frozen in the same place.','The nimble goalkeeper moved quickly to reach the ball.','动作迟缓且僵住与 nimble 的敏捷义相反。'),[Q(1,'How did the goalkeeper respond?','He shifted quickly and caught the ball.','He remained still until the ball stopped.','He wrote a report after the match.','nimble.s1 指动作迅速灵活。'),Q(1,'Which person is nimble-fingered?','A pianist who moves her fingers quickly and precisely.','A person who cannot move their fingers.','A runner who reads slowly.','nimble 可形容手指动作灵巧。','meaning'),Q(1,'Nimble can describe quickness of?','movement or thought','weight only','age only','该词既可形容身体动作，也可形容思维。','meaning'),Q(1,'Which spelling is correct?','nimble','nible','nimbel','现代拼写保留了后来出现的非词源 b。','spelling')]);
P('nine','From Old English nigen, from Proto-Germanic *newun and Indo-European *newn; it is the cardinal number after eight, and it can identify age, size, or an item numbered nine.',[C('nine.s1','数词','The box contained nine glass jars, arranged in three neat rows on the shelf.','盒子里装着九个玻璃罐，在架子上整齐地排成三行。','The box contained nine glass jars / arranged in three neat rows / on the shelf.','nine.s1 是八之后、十之前的基数词。','三行各三个，共九个。'),C('nine.s2','通用','The child is nine and has just started a junior swimming class at the community pool.','这个孩子九岁，刚开始在社区泳池参加少年游泳课。','The child is nine / and has just started / a junior swimming class / at the community pool.','nine.s2 可表示年龄，也可标记编号或时间段。','nine 在此表示孩子的年龄。')],M('The shelf held nine jars, but the inventory listed eight and claimed the counts matched exactly.','The shelf held nine jars, matching the inventory count of nine.','九个物品不能与清单上的八个相符。'),[Q(1,'How many jars were in the box?','Nine.','Eight.','Nineteen.','nine.s1 表示数量九。'),Q(2,'How old is the child?','Nine years old.','Ninety years old.','Nineteen months old.','nine.s2 表示年龄。'),Q(1,'Which number comes immediately after eight?','nine','seven','ten','九位于八之后、十之前。','number'),Q(2,'In “bus number nine,” nine identifies?','the route or item number','the age of the bus','a nine-sided bus','nine.s2 可作编号。','meaning')]);
P('niner','A radio-communication pronunciation of nine, with an added final syllable to make the spoken number clearer; the FAA’s radiotelephony table standardizes its pronunciation as “NIN-ER.”',C('niner.s1','通用','The controller read the aircraft’s final digit as niner so the pilot could distinguish the number clearly over the radio.','管制员把飞机编号的末位读作 niner，让飞行员能在无线电中清楚分辨这个数字。','The controller read the aircraft’s final digit as niner / so the pilot could distinguish the number / clearly over the radio.','niner 是无线电通话中数字 nine 的规范口语读法。','管制员使用清晰读法传递编号。'),M('The radio operator said “niner” meant the number eight and entered the aircraft as flight 8.','The radio operator said “niner” meant nine and entered the aircraft as flight 9.','niner 是 nine 的无线电读法，不是 eight。','number'),[Q(1,'What number does niner represent?','Nine.','Eight.','Nineteen.','niner 是数字九的无线电读法。'),Q(1,'Why did the controller say niner?','To make the number clearer over the radio.','To describe a nickel coin.','To say the aircraft was newly built.','加一个音节有助于无线电中清晰辨认。'),Q(1,'How does the FAA pronunciation table render niner?','NIN-ER','NINE-TH','NIN-TEE','FAA 表中写作 NIN-ER。','usage'),Q(1,'Where is niner especially useful?','In aviation or other radio communication.','In a printed newspaper headline only.','As a chemical name for nitric acid.','niner 是无线电数字读法。','context')]);
P('nineteen','From Old English nigontyne, a compound of nine + ten in the older counting pattern; it names the number after eighteen and before twenty, or a person/item marked 19.',[C('nineteen.s1','数词','Nineteen delegates attended the workshop, one fewer than the organizers had expected.','十九名代表参加了研讨会，比组织者预期少一人。','Nineteen delegates attended the workshop / one fewer / than the organizers had expected.','nineteen.s1 指十八之后、二十之前的基数词。','人数在十八与二十之间。'),C('nineteen.s2','通用','The runner wearing nineteen crossed the finish line just behind the leader.','穿十九号号码布的跑者紧跟在领先者之后冲过终点。','The runner wearing nineteen / crossed the finish line / just behind the leader.','nineteen.s2 可作年龄、编号或标签中的数字。','号码布用十九标记参赛者。')],M('The attendance sheet lists nineteen delegates, but the organizer says exactly twenty people came and all names are listed.','The attendance sheet lists nineteen delegates, one fewer than the expected twenty.','若预期二十人而实际十九人，就不是全部二十人到场。','number'),[Q(1,'How many delegates attended?','Nineteen.','Eighteen.','Ninety.','nineteen.s1 是参加人数。'),Q(2,'What did the number on the runner’s shirt identify?','The runner’s race number.','The runner’s age as ninety.','The count of delegates.','nineteen.s2 可表示编号。'),Q(1,'Which number is nineteen?','18 + 1','9 + 1','20 + 1','nineteen 是十八之后的数。','number'),Q(2,'In “the nineteen bus,” nineteen most likely names?','the route number','the bus’s age in years','the number of passengers currently aboard','数字可以用来标记公交线路。','meaning')]);
P('nineteenth','From nineteen + the ordinal ending -th; it means occupying position 19 in a sequence.',C('nineteenth.s1','通用','The nineteenth page contains the diagram that explains how the filtration system works.','第十九页上有一张图，解释过滤系统的工作方式。','The nineteenth page / contains the diagram / that explains how / the filtration system works.','nineteenth 指顺序中位于前十八项之后的第十九项。','页码标明该图所在位置。'),M('The report placed the diagram on the nineteenth page, then told readers to turn to page eighteen to find it.','The report placed the diagram on the nineteenth page and directed readers there.','第十九页应在第十八页之后，前后指示要一致。','number'),[Q(1,'Where is the diagram?','On page 19.','On page 18.','On page 90.','nineteenth.s1 表示顺序第十九页。'),Q(1,'What kind of number is nineteenth?','An ordinal number.','A cardinal number meaning 19 objects.','A fraction meaning one of 19 parts.','-th forms this ordinal.','number'),Q(1,'Which item comes nineteenth in a line?','The one after the eighteenth.','The one after the ninetieth.','The one before the first.','序数词表示顺序位置。'),Q(1,'Choose the correctly spelled ordinal.','nineteenth','nineteeneth','nineteenthieth','nineteenth 是正确拼写。','spelling')]);
P('nineties','From the plural of ninety; it can denote the years 1990–1999 (or another decade ending in 9) or a person’s age from 90 to 99.',[C('nineties.s1','通用','The band reunited in the nineties, releasing its first new album in 1994.','乐队在九十年代重聚，并于1994年发行首张新专辑。','The band reunited in the nineties / releasing its first new album / in 1994.','nineties.s1 常指一个世纪中以90到99结尾的十年。','1994年属于20世纪90年代。'),C('nineties.s1','通用','In her nineties, the retired teacher still writes a letter to each former student every year.','这位退休教师九十多岁了，仍每年给每位以前的学生写信。','In her nineties / the retired teacher still writes a letter / to each former student / every year.','人到了 nineties 表示年龄在九十至九十九岁之间。','九十多岁的教师仍坚持与学生通信。')],M('The album came out in 1994, so the biography says it was released in the nineties of the eighteenth century.','The album came out in 1994, so it was released in the 1990s.','1994属于20世纪90年代，不是18世纪90年代。','number'),[Q(1,'When did the band reunite?','During the 1990s.','During the 1890s.','In the 2090s.','例句将 1994 放在 nineties。'),Q(1,'How old is the retired teacher?','Ninety-six.','Sixty-nine.','Nineteen.','ninety-six 表示年龄96岁。'),Q(1,'“She is in her nineties” means she is?','between 90 and 99 years old','between 19 and 29 years old','exactly 90 years old only','nineties 描述90至99岁的年龄段。','number'),Q(1,'Which year belongs to the 1990s?','1997','1987','2007','1997 falls between 1990 and 1999.','number')]);
P('ninetieth','From ninety + the ordinal ending -th; it means occupying position 90 in a sequence.',C('ninetieth.s1','通用','The ninetieth runner crossed the finish line several minutes after the first group.','第九十名跑者在第一组之后几分钟冲过终点。','The ninetieth runner / crossed the finish line / several minutes after / the first group.','ninetieth 表示顺序中的第九十位。','跑者的名次是90。'),M('The ninetieth runner was listed as number eighty-nine, even though eighty-nine runners had already finished.','The ninetieth runner was listed after the eighty-ninth finisher.','第九十位应排在第八十九位之后。','number'),[Q(1,'How many runners had finished before the ninetieth runner?','Eighty-nine.','Nineteen.','Ninety.','序数第九十表示前面已有八十九位。'),Q(1,'Ninetieth is an?','ordinal','adverb of frequency','fraction','-th marks an ordinal position.','number'),Q(1,'Which runner is ninetieth?','The one in position 90.','The one with a count of 90 laps necessarily.','The one after runner 99.','ninetieth 指第90位。'),Q(1,'Which spelling is correct?','ninetieth','ninetyth','ninetyeth','ninety drops y and adds -ieth in this ordinal spelling.','spelling')]);
P('ninety','From Old English nigontig, built from nine + the group-of-ten ending -tig; it means nine times ten, and can refer to age or the 1990s.',[C('ninety.s1','数词','The repair crew ordered ninety bolts so every panel could be secured with two fasteners.','维修组订购了九十枚螺栓，好让每块面板都能用两个紧固件固定。','The repair crew ordered ninety bolts / so every panel could be secured / with two fasteners.','ninety.s1 是九乘十，即90。','45块面板各用两枚螺栓，共90枚。'),C('ninety.s2','时间','Her grandmother turned ninety last month and celebrated with a small family lunch.','她的祖母上个月满九十岁，并与家人简单共进午餐。','Her grandmother turned ninety / last month / and celebrated / with a small family lunch.','ninety.s2 可表示年龄90岁，也可指90年代。','turn ninety 表示年满九十岁。')],M('The crew ordered ninety bolts, which the invoice incorrectly counted as nine because one zero was dropped.','The crew ordered ninety bolts, and the invoice recorded the full count of ninety.','漏掉一个零会把九十误写成九。','number'),[Q(1,'How many bolts did the repair crew order?','90.','9.','19.','ninety.s1 表示九十。'),Q(2,'How old did the grandmother turn?','90.','19.','99.','ninety.s2 表示年满九十岁。'),Q(1,'Ninety equals?','nine times ten','nine plus one','nineteen times ten','ninety is 9 × 10.','number'),Q(2,'“Music from the nineties” usually refers to?','music from the 1990–1999 decade','music by people aged exactly 90','music played 90 times a night','ninety can identify the decade from 1990 through 1999.','meaning')]);
P('ninth','From Old English nigoða/nigende, later reshaped in Middle English under the influence of nine; it means position nine or one of nine equal parts.',[C('ninth.s1','数词','Her name appeared ninth on the list, after eight other applicants had been interviewed.','她的名字排在名单第九位，前面已经面试过八名申请人。','Her name appeared ninth on the list / after eight other applicants / had been interviewed.','ninth.s1 表示序列中的第九位。','前面八位之后是第九位。'),C('ninth.s2','数学','He divided the ribbon into nine equal pieces and used one ninth to mark the edge of the poster.','他把丝带分成九等份，取其中九分之一标记海报边缘。','He divided the ribbon into nine equal pieces / and used one ninth / to mark the edge / of the poster.','ninth.s2 可作名词，指九个相等部分中的一个。','one ninth 是九等分中的一份。')],M('Eight people had been interviewed before her, but the clerk marked her position as the eighth.','Eight people had been interviewed before her, so the clerk marked her ninth.','前面八人后面的顺序位置是第九，不是第八。','number'),[Q(1,'What position did her name have on the list?','Ninth.','Eighth.','Ninetieth.','ninth.s1 是顺序第九。'),Q(2,'What does one ninth represent?','One of nine equal parts.','Nine complete objects.','One part out of ninety.','ninth.s2 表示九等分之一。'),Q(1,'Which position follows eighth?','ninth','seventh','nineteenth','ninth follows eighth.','number'),Q(2,'If a cake is cut into nine equal pieces, one piece is?','one ninth of the cake','the ninth cake','nine cakes','一块占九等份之一。','number')]);
P('ninthly','From ninth + the adverbial suffix -ly; it is a formal sequencing word used to introduce the ninth point in a list or argument.',C('ninthly.s1','语法','Ninthly, the proposal sets aside money for repairs, after explaining staffing, training, equipment, and five other priorities.','第九，提案在说明人员、培训、设备和另外五项优先事项后，拨出资金用于维修。','Ninthly / the proposal sets aside money for repairs / after explaining / eight earlier priorities.','ninthly 用于正式列举，提示接下来是第九点。','它位于八个先前要点之后。'),M('Ninthly, the speaker introduced the first point of the talk before mentioning any of the eight earlier points.','Firstly, the speaker introduced the first point; ninthly would introduce a ninth point later.','ninthly 表示第九项，不是第一项。','number'),[Q(1,'What does “Ninthly” signal?','The ninth point in a sequence.','The first point.','A count of nine objects.','ninthly.s1 用于引出第九点。'),Q(1,'How many earlier priorities are mentioned before repairs?','Eight.','One.','Ninety.','第九点之前有八项。'),Q(1,'Which word would introduce the first item?','Firstly.','Ninthly.','Ninetieth.','序列第一项应由 firstly 引入。','number'),Q(1,'Ninthly is most appropriate in?','a formal numbered list or argument','a casual greeting instead of hello','a chemical formula for nitric acid','它是正式列举顺序的副词。','register')]);
P('nip','From late Middle English nippen, probably related to Low German and Dutch verbs meaning pinch or bite; it means to pinch or bite quickly and sharply, and can describe a sharp cold sensation.',C('nip.s1','通用','The puppy tried to nip my glove when I reached toward its toy, so I gave it a chew rope instead.','我伸手去拿小狗的玩具时，它想咬我的手套，于是我给了它一根磨牙绳。','The puppy tried to nip my glove / when I reached toward its toy / so I gave it / a chew rope instead.','nip.s1 指突然、迅速地轻咬或掐一下；也可形容寒冷带来的刺痛感。','小狗试图迅速咬手套。'),M('The puppy nipped the glove gently without touching it or making any tooth contact.','The puppy nipped the glove with a quick, sharp bite.','nip 表示短促地掐或咬，不能完全没有接触。'),[Q(1,'What did the puppy try to nip?','The glove.','The chew rope after it was given.','A newspaper on the table.','nip 指小狗迅速咬手套。'),Q(1,'Which action is a nip?','A quick, sharp pinch on the arm.','A slow full meal.','A long hug with no pressure.','短促的掐一下符合 nip。'),Q(1,'“A nip in the air” describes?','a sharp, chilly feeling','a warm summer afternoon','a radio pronunciation of nine','nip 也可形容空气中的刺骨寒意。','meaning'),Q(1,'What was the chew rope for?','To give the puppy a safer object to bite.','To neutralize the puppy’s name.','To print a newsreel.','给小狗磨牙绳是为了引导它咬合适的物品。','context')]);
P('nirvana','From Sanskrit nirvāṇa “extinction, disappearance,” literally “blowing out”; in Buddhism it is liberation from suffering, and figuratively it can mean perfect peace or bliss.',C('nirvana.s1','宗教','The guide explained that nirvana in Buddhism is liberation from craving and suffering, not simply a pleasant holiday.','导览员解释说，佛教中的涅槃是摆脱欲望和痛苦，并不只是一次愉快的假期。','The guide explained / that nirvana in Buddhism is liberation / from craving and suffering / not simply a pleasant holiday.','nirvana.s1 指佛教追求的解脱境界，也可比喻极乐或安宁。','句子说明其宗教含义超出普通愉快体验。'),M('The guide defined Buddhist nirvana as a brief shopping trip that leaves all craving and suffering unchanged.','The guide described nirvana as liberation from craving and suffering.','佛教涅槃不是短暂消遣，而是解脱痛苦和欲望的境界。','meaning'),[Q(1,'What does nirvana mean in the Buddhist explanation?','Liberation from craving and suffering.','A small market for a special product.','A count of ninety items.','nirvana.s1 的佛教义是解脱。'),Q(1,'What is the literal image behind the Sanskrit word?','A blowing out or extinction.','A bright newscast.','A nickel alloy returning to shape.','nirvāṇa 的词源字面意为吹灭、熄灭。'),Q(1,'Which figurative use fits nirvana?','The quiet garden felt like nirvana after the noisy station.','The nine-hour meeting was a nirvana because it was a nightmare.','The newspaper printed a nirvana of current events.','nirvana 可比喻极乐安宁。','meaning'),Q(1,'Why did the guide say nirvana is more than a holiday?','It refers to spiritual liberation, not merely temporary pleasure.','It names a place to buy a train ticket.','It means a person is ninety years old.','涅槃是宗教解脱境界，不是普通休假。','distinction')]);
P('nitinol','A name built from nickel + titanium + NOL, the abbreviation for the Naval Ordnance Laboratory; nitinol is a nickel–titanium shape-memory alloy that can recover a set shape after deformation.',C('nitinol.s1','工程','The engineer bent the nitinol wire, warmed it, and watched it return to its memorized coil shape.','工程师弯折镍钛诺丝，将其加热后，观察它恢复到预先设定的线圈形状。','The engineer bent the nitinol wire / warmed it / and watched it return / to its memorized coil shape.','nitinol 是镍钛形状记忆合金，受热后可恢复设定形状。','加热后金属丝回到原来的线圈形态。'),M('The lab called the steel wire nitinol even though it contained no nickel or titanium and could not recover its shape.','The lab identified the nickel–titanium shape-memory wire as nitinol.','nitinol 特指镍钛合金，不是普通钢丝。','word-choice'),[Q(1,'What happened when the nitinol wire was warmed?','It returned to its memorized coil shape.','It turned into newsprint.','It became electrically charged like a neutron.','nitinol.s1 是形状记忆合金。'),Q(1,'Which metals form nitinol?','Nickel and titanium.','Nitrogen and tin.','Copper and silver only.','nitinol 的合金成分为镍和钛。','word-formation'),Q(1,'What does the NOL part of the name refer to?','Naval Ordnance Laboratory.','Nighttime Observation List.','Neutrality of Liquids.','NOL 是 Naval Ordnance Laboratory 的缩写。'),Q(1,'Why is nitinol useful in a shape-memory device?','It can recover a set shape after deformation.','It dissolves instantly in water.','It is a newspaper printing process.','形状恢复能力是这类合金的用途特点。','context')]);
P('nitrate','From nitre + the chemical suffix -ate; a nitrate is a compound containing the nitrate ion, NO₃⁻, such as sodium nitrate.',C('nitrate.s1','化学','The soil test showed low nitrate levels, so the farmer adjusted the fertilizer plan to protect the young crop.','土壤检测显示硝酸盐含量偏低，因此农民调整了施肥方案来保护幼苗。','The soil test showed low nitrate levels / so the farmer adjusted / the fertilizer plan / to protect the young crop.','nitrate 是含硝酸根离子 NO₃⁻ 的化合物。','土壤检测测量硝酸盐，施肥方案据此调整。'),M('The worksheet identified nitrate as a single nitrogen atom, not as a compound containing the NO₃ group.','The worksheet identified nitrate as a compound containing the NO₃ group.','nitrate 是含硝酸根的化合物，不是单个氮原子。','word-choice'),[Q(1,'What did the soil test find?','Low nitrate levels.','A high nickel coin count.','No nitrogen in the atmosphere.','nitrate.s1 是土壤中可测量的化合物。'),Q(1,'Which ion is characteristic of nitrate?','NO₃⁻','N₂','Ni⁺ only','硝酸盐含有硝酸根离子 NO₃⁻。'),Q(1,'Why did the farmer adjust the fertilizer plan?','The soil test showed low nitrate levels.','The crop had become a newsreel.','A night person requested a change.','施肥决定根据土壤检测结果作出。','context'),Q(1,'Sodium nitrate is an example of a?','nitrate compound','pure nitrogen atom','nickel–titanium alloy','硝酸钠含硝酸根，属于硝酸盐。','meaning')]);
P('nitric','From nitre + -ic, first used in 1794 for something pertaining to nitre; nitric acid is HNO₃, distinct from nitrous acid.',C('nitric.s1','化学','The safety label identified the sealed bottle as nitric acid and directed trained staff to follow the laboratory handling procedure.','安全标签注明密封瓶内是硝酸，并要求受训人员遵守实验室操作规程。','The safety label identified the sealed bottle / as nitric acid / and directed trained staff / to follow the laboratory handling procedure.','nitric 指与氮或硝酸有关的；nitric acid 即硝酸 HNO₃。','标签明确了酸的名称，工作人员依规处理。'),M('The report called HNO₃ nitric acid and then classified it as nitrous acid, although the two names identify different acids.','The report called HNO₃ nitric acid and distinguished it from nitrous acid.','nitric acid 和 nitrous acid 是不同的含氮酸。','confusable'),[Q(1,'What formula identifies nitric acid in the example?','HNO₃','N₂','NiTi','nitric.s1 指硝酸 HNO₃。'),Q(1,'Which term is distinct from nitric acid?','nitrous acid','nitrate as a broad ion family only','nighttime','nitric 与 nitrous 对应不同的酸。','confusable'),Q(1,'What did the label require staff to follow?','The laboratory handling procedure.','A newsstand timetable.','A nine-part list.','例句要求按实验室规程处理。','context'),Q(1,'Nitric is historically formed from nitre and?','-ic','-ly','-er','-ic forms an adjective meaning related to or derived from nitre.','word-formation')]);
P('nitrogen','Named in 1790 from French nitrogène, built from nitre + -gène “producing”; nitrogen is element N, a colourless gas that forms most of Earth’s atmosphere and is also essential to plants.',[C('nitrogen.s1','化学','Nitrogen makes up most of the air in the sealed chamber, although the sensor also detects a small amount of oxygen.','氮气构成密闭舱内空气的大部分，不过传感器也检测到少量氧气。','Nitrogen makes up most of the air / in the sealed chamber / although the sensor also detects / a small amount of oxygen.','nitrogen.s1 指化学元素氮；常温下氮气无色，约占大气的大部分。','舱内空气以氮气为主，也含少量氧气。'),C('nitrogen.s2','农业','The gardener added a nitrogen-rich fertilizer because the leafy vegetables were growing slowly in depleted soil.','由于土壤贫瘠、叶菜生长缓慢，园丁施用了富含氮素的肥料。','The gardener added a nitrogen-rich fertilizer / because the leafy vegetables were growing slowly / in depleted soil.','nitrogen.s2 指土壤和生物体所需的氮素营养。','氮素是植物生长所需营养之一。')],M('The label said nitrogen is a green liquid metal that makes up only a tiny fraction of the air.','The label said nitrogen is a colourless gas that makes up most of the atmosphere.','氮不是绿色液态金属，且氮气占大气的大部分。','meaning'),[Q(1,'What makes up most of the chamber’s air?','Nitrogen.','Oxygen only.','Nickel vapour.','nitrogen.s1 指空气中的主要成分。'),Q(2,'Why did the gardener add nitrogen-rich fertilizer?','The leafy vegetables were growing slowly in depleted soil.','The chamber needed more nickel.','The leaves were already growing too quickly.','nitrogen.s2 是植物所需养分。'),Q(1,'What is the chemical symbol for nitrogen?','N','Ni','Na','氮的元素符号是 N。','spelling'),Q(2,'In agriculture, nitrogen is important as?','a nutrient plants need','a five-cent coin','a word for the 1990s','nitrogen.s2 指植物营养元素。','meaning')]);
P('no','From Old English nā, a contraction of ne “not” + ā “ever”; it can mean not any, serve as a refusal or denial, or name a negative answer or vote.',[C('no.s1','语法','There is no clean water left in the tank, so the crew must refill it before opening the clinic.','水箱里已经没有干净水了，因此工作人员必须在诊所开门前把它加满。','There is no clean water left / in the tank / so the crew must refill it / before opening the clinic.','no.s1 作限定词，表示没有、无任何。','no 修饰不可数名词 water。'),C('no.s2','通用','“Would you like another cup?” “No, thank you; I have had enough.”','“你还想再来一杯吗？”“不用了，谢谢；我已经够了。”','“Would you like another cup?” / “No, thank you / I have had enough.”','no.s2 可作回答，表示拒绝、否认或不同意。','回答者礼貌地拒绝续杯。'),C('no.s3','通用','The committee recorded four yes votes and two noes on the proposal to extend the opening hours.','委员会就延长开放时间的提案记录了四张赞成票和两张反对票。','The committee recorded four yes votes / and two noes / on the proposal / to extend the opening hours.','no.s3 作名词，no 可指否定回答或反对票，复数常写 noes。','noes 是投票反对的票数。')],M('The tank contains no clean water, so the clinic opened using a full supply of clean water from that same tank.','The tank contains no clean water, so the crew must refill it before the clinic opens.','“没有干净水”与“水箱里有充足干净水”互相矛盾。'),[Q(1,'What was left in the tank?','No clean water.','A full tank of clean water.','Four yes votes.','no.s1 表示没有水。'),Q(2,'Why did the customer say no?','They did not want another cup.','They wanted three more cups.','They were voting on clinic hours.','no.s2 表示拒绝续杯。'),Q(3,'How many votes opposed the proposal?','Two.','Four.','Six.','noes 是反对票，例句中有两票。'),Q(1,'Which sentence uses no as a determiner?','There is no milk in the fridge.','No, I disagree.','The motion received two noes.','no 修饰名词 milk，表示没有。','grammar')]);
P('no matter','A fixed phrase combining no + matter; it means “regardless of what happens” or “whatever the circumstances,” introducing a condition that does not change the result.',C('no matter.s1','语法','No matter the weather, the rescue team will keep the radio station staffed through the night.','不管天气如何，救援队都会整夜安排人员值守无线电台。','No matter the weather / the rescue team will keep / the radio station staffed / through the night.','no matter 引出不影响后续结果的条件，常接名词或疑问词从句。','天气变化不会改变值守安排。'),M('No matter the weather, the team will cancel every shift whenever the forecast is pleasant.','No matter the weather, the team will keep the radio station staffed.','no matter 表示无论条件如何结果不变，不能再说好天气就取消。'),[Q(1,'What will the rescue team do regardless of the weather?','Keep the radio station staffed.','Close the station whenever it rains.','Leave the radios at a newsstand.','no matter.s1 表示天气不改变值守安排。'),Q(1,'Which phrase is closest to no matter here?','regardless of','because of','only if','no matter 引出不影响结果的条件。'),Q(1,'Which completion is grammatical?','No matter what happens, call the duty officer.','No matter what happen, call the duty officer.','No matter happens what, call the duty officer.','what 从句中主语 what 按单数处理，动词用 happens。','grammar'),Q(1,'The phrase tells us that?','the result stays the same despite a condition','the condition is the only reason for the result','the speaker refuses to answer a question','no matter 表达让步关系。','meaning')]);
P('no matter how','A fixed phrase built from no matter + how; it means “however much or in whatever way,” stressing that the result remains true despite the degree or manner of an action.',C('no matter how.s1','语法','No matter how carefully the team checks the bridge, it records every measurement before reopening the road.','无论团队检查桥梁多么仔细，重新开放道路前都会记录每一项测量数据。','No matter how carefully the team checks the bridge / it records every measurement / before reopening the road.','no matter how 后接形容词或副词及从句，表示“无论多么……”。','检查程度不会改变记录全部数据的要求。'),M('No matter how carefully she checked the form, she left every required field blank and submitted it as complete.','No matter how carefully she checked the form, she filled in every required field before submitting it.','声称仔细检查且完整提交，却把所有必填栏留空，前后矛盾。'),[Q(1,'What does the team do regardless of how carefully it checks?','Records every measurement.','Reopens the road before checking.','Leaves the bridge unmeasured.','no matter how 引出不影响记录要求的检查程度。'),Q(1,'Which phrase means “however carefully”?','no matter how carefully','no matter the careful','no matter how care','how 后可接副词 carefully。','grammar'),Q(1,'“No matter how late it gets, call me” means?','Call me even if it becomes very late.','Call me only if it is early.','Do not call after sunset.','该短语表示时间多晚都不改变指令。','meaning'),Q(1,'Choose the grammatical sentence.','No matter how difficult the task is, we will try.','No matter how difficult is the task, we will try.','No matter difficult how the task, we will try.','常用语序是 how + 形容词 + 主语 + be。','grammar')]);
P('no one','A phrase of no + one; it means not a single person and normally takes a singular verb.',C('no one.s1','语法','No one on the review panel had seen the revised map before the meeting began.','评审小组中没有人在会议开始前见过修订后的地图。','No one on the review panel / had seen the revised map / before the meeting began.','no one 表示没有任何人，通常作单数主语。','had seen 与单数主语 no one 搭配。'),M('No one on the panel have read the map, although the sentence says every member read it.','No one on the panel has read the map.','no one 通常接单数动词；原句主谓形式不一致且语义冲突。','grammar'),[Q(1,'Who had seen the revised map before the meeting?','Nobody on the panel.','Every panel member.','Only the mapmaker.','no one 表示没有任何人。'),Q(1,'Which verb agrees with no one?','No one knows the answer.','No one know the answer.','No one are knowing the answer.','no one 通常按单数处理，使用 knows。','grammar'),Q(1,'No one means?','not a single person','not one object among several','the next person in line','该短语指没有任何人。'),Q(1,'Choose the natural expression.','No one was available to answer.','No one were available to answer.','No one have available to answer.','no one 与单数 was 搭配。','grammar')]);
P('nobility','From Old French nobilite and Latin nobilitas, from nobilis “well-known, prominent”; it means the hereditary upper class or the quality of high moral character.',[C('nobility.s1','通用','The history exhibit described the nobility as a social class whose titles and privileges were often inherited.','历史展览把贵族阶级描述为一个通常世袭头衔和特权的社会阶层。','The history exhibit described the nobility / as a social class / whose titles and privileges / were often inherited.','nobility.s1 指拥有较高社会等级或世袭头衔的贵族阶层。','继承头衔和特权是社会阶层的特征。'),C('nobility.s2','通用','Her nobility of character showed when she admitted the mistake and gave credit to the colleague who had helped her.','她承认错误并把功劳归给帮助过她的同事，体现出高尚品格。','Her nobility of character showed / when she admitted the mistake / and gave credit / to the colleague who had helped her.','nobility.s2 可指高尚的道德品质或人格。','诚实认错并感谢他人体现品格高尚。')],M('The biography praised his nobility of character because he stole credit from the colleague who did the work.','The biography praised his nobility of character because he gave credit to the colleague who did the work.','抢占他人功劳不是高尚品格。','meaning'),[Q(1,'What did the exhibit mean by the nobility?','The hereditary upper social class.','People who work at the newspaper.','Anyone attending the meeting.','nobility.s1 指贵族阶层。'),Q(2,'What showed her nobility of character?','She admitted her error and credited her colleague.','She hid the mistake and claimed another person’s work.','She inherited a title without doing anything.','nobility.s2 指高尚品格。'),Q(1,'A member of the nobility may hold?','an inherited title','a chemical symbol','a newsstand receipt','传统意义上的贵族可能拥有世袭头衔。','meaning'),Q(2,'Which action demonstrates moral nobility?','Taking responsibility and sharing credit fairly.','Blaming an innocent coworker.','Keeping all credit for another person’s work.','诚实负责、肯定他人贡献体现高尚品格。','context')]);
P('noble','From Old French noble and Latin nobilis “well-known, prominent, high-born”; it can describe admirable moral character, aristocratic birth, or a person of high rank.',[C('noble.s1','书面','The firefighter made a noble effort to rescue the dog, even though the smoke forced the team to withdraw.','消防员奋力救狗，虽然后来浓烟迫使队伍撤退，这一努力仍值得敬佩。','The firefighter made a noble effort / to rescue the dog / even though the smoke / forced the team to withdraw.','noble.s1 指道德上高尚、勇敢、值得敬佩的。','冒险救援体现勇气和善意。'),C('noble.s2','历史','The castle once belonged to a noble family whose lands were granted by the crown.','这座城堡曾属于一个贵族家庭，其领地由王室授予。','The castle once belonged / to a noble family / whose lands were granted / by the crown.','noble.s2 作形容词指贵族出身或属于贵族阶层。','家族拥有王室授予的封地。'),C('noble.s3','历史','A noble addressed the assembly and spoke on behalf of the families who held titles in the region.','一位贵族成员在集会上发言，代表当地拥有头衔的家族。','A noble addressed the assembly / and spoke on behalf / of the families / who held titles in the region.','noble.s3 作名词，指拥有贵族身份的人。','发言者代表拥有贵族头衔的家庭。')],M('The noble rescue effort was selfish and cruel, and the historical noble was described as a commoner with no rank.','The noble rescue effort was brave and generous; the noble belonged to a titled family.','同一处把 noble 解释为高尚和自私、贵族和平民，概念互相冲突。'),[Q(1,'Why was the firefighter’s effort called noble?','It was brave and aimed at saving the dog.','It was an inherited family title.','It was a person speaking at an assembly.','noble.s1 表示值得敬佩的高尚行为。'),Q(2,'What made the family noble in the castle example?','Its aristocratic status and granted lands.','Its work printing newspapers.','Its refusal to attend an assembly.','noble.s2 指贵族阶层的身份。'),Q(3,'Who is “a noble” in the final example?','A person of high birth or rank.','A morally admirable action only.','A family’s inherited land.','noble.s3 是名词，指贵族成员。'),Q(1,'Which sentence uses noble to mean morally admirable?','She made a noble choice to tell the truth.','The noble addressed the assembly.','The castle belonged to a noble family.','“noble choice” 描述高尚行为。','distinction')]);
P('nobleman','From noble + man; the compound names a man who belongs to the nobility or holds a high hereditary social rank.',C('nobleman.s1','社会','The nobleman funded a village school and asked that children from every family be admitted.','这位贵族男士资助了一所乡村学校，并要求接收每个家庭的孩子。','The nobleman funded a village school / and asked / that children from every family / be admitted.','nobleman 指属于贵族阶层的男性。','男性贵族资助学校并推动广泛入学。'),M('The archive identified the nobleman as a woman who held the title through her own birth.','The archive identified the nobleman as a man of noble birth.','nobleman 指男性贵族；女性对应 noblewoman。','confusable'),[Q(1,'Who funded the village school?','A man belonging to the nobility.','A woman who held a title.','A committee of schoolchildren.','nobleman 指男性贵族。'),Q(1,'What did he ask about admission?','Children from every family should be admitted.','Only titled families should attend.','No one should be admitted.','例句说明他要求广泛接收学生。','context'),Q(1,'What is the feminine counterpart of nobleman?','noblewoman','nobility','noblement','noblewoman 指女性贵族。','confusable'),Q(1,'The noun nobleman is formed from?','noble + man','no + man','nobility + moon','该词由 noble 与 man 组成。','word-formation')]);
P('noblewoman','From noble + woman; the compound names a woman who belongs to the nobility or holds a high hereditary social rank.',C('noblewoman.s1','社会','The noblewoman opened her estate garden to local school groups and explained its history to the children.','这位贵族女士向当地学校团体开放庄园花园，并向孩子们讲解它的历史。','The noblewoman opened her estate garden / to local school groups / and explained its history / to the children.','noblewoman 指属于贵族阶层的女性。','她拥有庄园并参与历史讲解。'),M('The portrait caption called the woman a noblewoman but stated that she was a man who held the title.','The portrait caption called the woman a noblewoman because she was a female member of the nobility.','noblewoman 指女性贵族，与男性贵族 nobleman 区分。','confusable'),[Q(1,'Who opened the estate garden?','A woman from the nobility.','A male nobleman.','A school group.','noblewoman 指女性贵族。'),Q(1,'Who visited the garden?','Local school groups.','Only the estate owner’s ancestors.','The newspaper printers.','例句说明庄园向学校团体开放。','context'),Q(1,'Which word names a female member of the nobility?','noblewoman','nobleman','nobility','noblewoman 指女性个人，nobility 指阶层或品格。','distinction'),Q(1,'Choose the correct compound.','noble + woman = noblewoman','noble + man = noblewoman','no + woman = noblewoman','noblewoman 由 noble 和 woman 构成。','word-formation')]);
P('nobody','From no + body, a compound with the sense “no person”; as a noun it can also mean an unimportant person with little influence.',[C('nobody.s1','语法','Nobody in the laboratory touched the sample before the safety officer had checked the label.','实验室里没有人在安全员检查标签前碰过样品。','Nobody in the laboratory / touched the sample / before the safety officer / had checked the label.','nobody.s1 表示没有任何人，通常接单数动词。','touched 与单数主语 nobody 搭配。'),C('nobody.s2','社会','Before the award, the young poet felt like a nobody, but her work soon reached readers across the country.','获奖前，这位年轻诗人觉得自己无足轻重，但她的作品很快传到了全国读者手中。','Before the award / the young poet felt like a nobody / but her work soon reached / readers across the country.','nobody.s2 可指不重要、没有影响力的人。','她觉得自己没有名气，后来作品广为传播。')],M('Nobody in the laboratory have touched the sample, but the report says every technician handled it.','Nobody in the laboratory has touched the sample.','nobody 通常作单数主语，且“没有人碰过”与“每人都操作过”矛盾。','grammar'),[Q(1,'Who touched the sample before the safety check?','No one.','Every technician.','Only the safety officer.','nobody.s1 表示没有人。'),Q(2,'Why did the poet feel like a nobody?','She felt unimportant before the award.','She had already become a national celebrity.','She worked in a laboratory.','nobody.s2 可指无足轻重的人。'),Q(1,'Which verb agrees with nobody?','Nobody has arrived yet.','Nobody have arrived yet.','Nobody are arrived yet.','nobody 通常按单数处理。','grammar'),Q(2,'Which sentence uses nobody to mean an unimportant person?','He felt like a nobody before his first book was published.','Nobody was in the room.','Nobody saw the signal.','felt like a nobody 表示觉得自己无足轻重。','distinction')]);
P('nocturnal','From Latin nocturnalis, from nocturnus “of the night,” related to nox/noctis “night”; it means active at night or happening during the night.',[C('nocturnal.s1','通用','Owls are nocturnal, hunting small animals after sunset and resting through much of the day.','猫头鹰是夜行性动物，日落后捕猎小动物，白天大部分时间休息。','Owls are nocturnal / hunting small animals after sunset / and resting / through much of the day.','nocturnal.s1 描述主要在夜间活动而非白天活动的生物。','猫头鹰日落后捕猎、白天休息。'),C('nocturnal.s2','通用','The observatory scheduled a nocturnal survey because the meteor shower could only be seen after dark.','天文台安排了一次夜间观测，因为流星雨只有天黑后才能看到。','The observatory scheduled a nocturnal survey / because the meteor shower / could only be seen / after dark.','nocturnal.s2 指发生在夜间的活动或事件。','观测安排在黑暗时段。')],M('The owl was called nocturnal even though it hunted only at midday and slept through every night.','The owl was called nocturnal because it hunted after sunset and rested during the day.','只在正午活动且整夜睡觉不符合夜行性。'),[Q(1,'When do the owls hunt?','After sunset.','Only at midday.','Only at dawn and never at night.','nocturnal.s1 指夜间活动。'),Q(2,'Why was the survey nocturnal?','The meteor shower was visible only after dark.','The team could see it best at noon.','It surveyed newspaper printing.','nocturnal.s2 指夜间进行的观测。'),Q(1,'Which animal is nocturnal?','A bat that forages at night.','A bird that feeds only at noon.','A fish that lives in a river but never moves.','夜间觅食的蝙蝠符合 nocturnal。','meaning'),Q(2,'A nocturnal event happens?','during the night','once every ninety years','before every morning only','nocturnal 可形容夜间发生的事。','distinction')]);
P('nod','Of uncertain origin; the verb has meant to move the head briefly in agreement, greeting, or direction since the late 14th century, and also to let the head droop while drowsy.',[C('nod.s1','交际','When the guide asked whether everyone could hear, Mina nodded and pointed toward the back of the hall.','导游问大家是否都听得见时，米娜点头并指向大厅后方。','When the guide asked whether everyone could hear / Mina nodded / and pointed / toward the back of the hall.','nod.s1 指上下轻动头部表示同意、招呼或示意。','点头和指向后方都构成回应。'),C('nod.s2','生活','During the late lecture, the exhausted student began to nod and nearly dropped his pen.','讲座进行到很晚时，疲惫的学生开始打盹，钢笔差点掉下来。','During the late lecture / the exhausted student began to nod / and nearly dropped his pen.','nod.s2 指困倦时头向前垂落、打盹。','学生因困倦点头打瞌睡。'),C('nod.s3','交际','The chair gave a nod to the speaker, signaling that she could begin her presentation.','主席向发言人点了点头，示意她可以开始演讲。','The chair gave a nod / to the speaker / signaling that she could begin / her presentation.','nod.s3 作名词，指一次点头动作。','主席用一个点头示意开始。')],M('The student nodded from exhaustion, but the sentence says he stayed fully alert and never let his head move.','The student nodded from exhaustion and began to doze during the lecture.','打盹时点头意味着头部会短暂下垂，不是完全不动。','meaning'),[Q(1,'How did Mina answer the guide?','She moved her head to show agreement.','She fell asleep on the floor.','She turned off the hall lights.','nod.s1 指点头回应。'),Q(2,'Why did the student begin to nod?','He was exhausted during the late lecture.','He was giving a formal greeting to the speaker.','He was directing the guide to the exit.','nod.s2 指困倦打盹。'),Q(3,'What did the chair give the speaker?','A brief head movement as a signal.','A printed newspaper.','A title in the nobility.','nod.s3 是点头动作。'),Q(1,'Which sentence uses nod to show agreement?','She nodded when asked if she understood.','She nodded off during the film.','The flower nodded in the wind.','本句中点头回应问题，表示理解。','distinction')]);
P('nodule','From Latin nodulus “small knot,” a diminutive of nodus “knot”; a nodule is a small lump or rounded swelling in tissue, minerals, or roots.',C('nodule.s1','医学','The scan showed a small nodule in the thyroid, and the doctor scheduled a follow-up to monitor it.','影像显示甲状腺里有一个小结节，医生安排了复查以观察变化。','The scan showed a small nodule / in the thyroid / and the doctor scheduled / a follow-up to monitor it.','nodule 指组织、矿物或根部的小结节、团块。','医生通过影像发现组织中的小团块并安排观察。'),M('The radiology report called the nodule a whole healthy organ rather than a small lump of tissue.','The radiology report described the nodule as a small lump of tissue.','nodule 指小团块，不是完整器官。','meaning'),[Q(1,'Where was the nodule seen?','In the thyroid.','In a radio transmitter.','In the newspaper’s headline.','nodule.s1 指影像中的小结节。'),Q(1,'Why did the doctor schedule follow-up?','To monitor the small lump for change.','To give it a nickname.','To move it to a newsstand.','结节需要观察变化。','context'),Q(1,'The word nodule is historically related to a Latin word meaning?','small knot','night visitor','no person','nodulus means “small knot.”','word-formation'),Q(1,'Which item could also be called a nodule?','A small rounded mineral lump.','A whole mountain range.','A radio programme.','nodule 可指矿物中的小团块。','meaning')]);
P('noise','From Old French noise “uproar, disturbance,” with a deeper origin that remains uncertain; it means an unpleasant or loud sound, or unwanted signals that obscure information.',[C('noise.s1','生活','The noise from the construction site made it difficult for the librarian to hear visitors at the front desk.','施工现场的噪声让图书管理员很难听清前台访客说话。','The noise from the construction site / made it difficult / for the librarian to hear visitors / at the front desk.','noise.s1 指响亮或令人不快的声音、喧闹声。','施工声干扰了对话。'),C('noise.s2','科技','A filter removed electrical noise from the recording so the technician could understand the faint sensor signal.','滤波器去除了录音中的电噪声，使技术员能听清微弱的传感器信号。','A filter removed electrical noise / from the recording / so the technician could understand / the faint sensor signal.','noise.s2 指遮蔽有用信息的电子信号或数据干扰。','滤波后微弱信号更容易识别。')],M('The filter added more unwanted interference to the recording, yet the technician claimed it had removed the noise.','The filter removed unwanted interference so the sensor signal became clearer.','noise 在电子语境中是干扰信息的杂讯；增加干扰并非去除。','meaning'),[Q(1,'What made it hard for the librarian to hear visitors?','Construction sounds.','A quiet room.','A small skin nodule.','noise.s1 指施工现场的喧闹声。'),Q(2,'What did the filter remove?','Unwanted electrical interference.','The useful sensor signal.','The technician’s voice alone.','noise.s2 是遮蔽信息的电子干扰。'),Q(1,'Which is a likely example of noise?','A loud drill interrupting a conversation.','A silent library with no sound.','A printed word on a page.','响亮的钻机声会打断交谈。','meaning'),Q(2,'In a recording, noise can?','hide a faint signal','make every signal easier to distinguish automatically','mean an absence of all sound','电子噪声会遮蔽有用信号。','context')]);
P('noiseless','A compound of noise + -less; it means making no sound at all or occurring without audible noise.',C('noiseless.s1','通用','The noiseless electric motor let the library’s ventilation system run without disturbing readers.','无声的电动机让图书馆通风系统运转而不打扰读者。','The noiseless electric motor / let the library’s ventilation system run / without disturbing readers.','noiseless 指几乎不发出声音的、无声的。','电机运转没有造成可听见的干扰。'),M('The noiseless motor roared so loudly that readers had to shout over it.','The noiseless motor ran quietly without disturbing readers.','轰鸣声会打扰读者，与 noiseless 的意思相反。'),[Q(1,'Why was the motor useful in the library?','It operated without disturbing readers.','It produced a loud roar.','It printed a newspaper.','noiseless.s1 指无声或不扰人的运转。'),Q(1,'What does the suffix -less mean in noiseless?','without','full of','in the manner of','-less 表示缺少某物。','word-formation'),Q(1,'Which device would best be called noiseless?','A fan that runs without audible sound.','A siren heard across town.','A drum played loudly.','没有可听见声音的风扇符合 noiseless。','meaning'),Q(1,'Choose the natural use.','The noiseless cart rolled through the hospital corridor.','The noiseless cart crashed loudly all night.','The cart noiselessly made no sound at all noiseless.','无声的推车在医院走廊轻轻移动。','context')]);
P('noisily','From noisy + the adverb-forming suffix -ly; it means in a loud, conspicuous, or rowdy way.',C('noisily.s1','通用','The children ran noisily down the corridor, so the teacher asked them to walk quietly near the classrooms.','孩子们在走廊里吵闹地奔跑，因此老师让他们在教室附近安静步行。','The children ran noisily / down the corridor / so the teacher asked them / to walk quietly near the classrooms.','noisily 是副词，修饰动作，表示发出许多声响或喧闹地进行。','跑步的声音打扰了附近教室。'),M('The children ran noisily through the hall, making no sound that anyone could hear.','The children ran noisily through the hall, talking and stomping loudly.','noisily 表示声音明显、喧闹，不是完全无声。','meaning'),[Q(1,'How did the children run down the corridor?','Loudly and disruptively.','Silently.','Only in a single file without moving.','noisily.s1 描述吵闹的动作。'),Q(1,'What did the teacher ask them to do near classrooms?','Walk quietly.','Shout more loudly.','Run into the library.','老师要求在教室附近安静步行。','context'),Q(1,'Which word does noisily modify?','ran','children','corridor','noisily 修饰动词 ran。','grammar'),Q(1,'Choose the adverb form.','The audience clapped noisily.','The audience clapped noisy.','The audience noisily applause.','动词 clapped 由副词 noisily 修饰。','grammar')]);
P('noisy','From noise + the adjective suffix -y; it describes a place or thing that is full of noise or makes a lot of sound.',C('noisy.s1','通用','The noisy café was crowded at lunchtime, and the team moved to a quieter room to finish its report.','这家咖啡馆午餐时段很嘈杂，团队于是换到更安静的房间完成报告。','The noisy café / was crowded at lunchtime / and the team moved / to a quieter room to finish its report.','noisy 指充满噪声或发出大量声音的。','午餐时咖啡馆人声嘈杂。'),M('The noisy café was so quiet that not a single sound could be heard, so the team called it noisy.','The noisy café was filled with conversations and clattering dishes.','完全安静与 noisy 的含义相反。'),[Q(1,'Why did the team move from the café?','It was crowded and loud.','It was too quiet to hear anything.','The report had become a nodule.','noisy.s1 指咖啡馆嘈杂。'),Q(1,'Which place is likely to be noisy?','A busy station during rush hour.','An empty soundproof room.','A sealed book with no one nearby.','繁忙车站通常有很多声音。','meaning'),Q(1,'What is the comparative form used in the example?','quieter','more quietest','noisyer','quiet 的比较级是 quieter。','grammar'),Q(1,'Choose the adjective.','a noisy street','a noisily street','a noiselessly street','noisy 修饰名词 street。','grammar')]);
P('nomad','From French nomade and Latin nomas, from Greek nomas “roaming for pasture,” related to nemein “to pasture”; a nomad travels with herds or lives without a fixed home.',[C('nomad.s1','社会','The nomad moved the family’s sheep to a higher pasture as the dry season advanced.','随着旱季推进，这位游牧民把家里的羊群转移到更高处的牧场。','The nomad moved the family’s sheep / to a higher pasture / as the dry season advanced.','nomad.s1 指随牲畜迁徙或没有固定住所的人。','转移羊群寻找牧场体现游牧生活。'),C('nomad.s2','社会','The article described the group’s nomad life, with temporary camps changing location several times each year.','文章描述了这个群体的游牧生活，他们每年数次更换临时营地。','The article described the group’s nomad life / with temporary camps / changing location / several times each year.','nomad.s2 可作形容词，表示不断迁移、不定居的。','临时营地一年多次迁移。')],M('The nomad settled permanently in one farmhouse and never moved the herd or changed location.','The nomad moved with the herd between seasonal pastures.','定居不迁徙与 nomad 的游牧含义相反。','meaning'),[Q(1,'Why did the nomad move the sheep?','To reach higher pasture during the dry season.','To take them to a newspaper shop.','To make the weather nocturnal.','nomad.s1 描述随牲畜寻找牧场的人。'),Q(2,'What characterized the group’s nomad life?','Temporary camps changed location several times a year.','The group lived permanently in one building.','The group never moved or traveled.','nomad.s2 指不断迁移、不定居的。'),Q(1,'A nomad is most closely associated with?','traveling from place to place','working only at a fixed city office','remaining in one place forever','nomad 指迁徙者或游牧者。','meaning'),Q(1,'What does the Greek source of nomad relate to?','pasturing or grazing','printing a newspaper','making a head movement','nomad traces to a word for roaming to pasture.','word-formation')]);
P('nomadic','From nomad + -ic; it describes a way of life involving movement with animals or frequent relocation without a permanent home.',[C('nomadic.s1','通用','The nomadic herders followed seasonal grasslands, moving their animals before the old pasture was exhausted.','游牧牧民跟随季节性草场，在旧牧场耗尽前转移牲畜。','The nomadic herders followed seasonal grasslands / moving their animals / before the old pasture / was exhausted.','nomadic.s1 指跟随牲畜或草场迁徙的生活方式。','转移牲畜寻找新草地是游牧活动。'),C('nomadic.s2','通用','After years of temporary jobs in different cities, Mara grew tired of her nomadic routine and chose one home base.','在不同城市做了多年临时工作后，玛拉厌倦了漂泊不定的生活，选择固定居所。','After years of temporary jobs / in different cities / Mara grew tired / of her nomadic routine.','nomadic.s2 可比喻频繁搬迁、没有固定居所的生活。','她长期在各城市漂泊。')],M('The nomadic herders stayed in one permanent camp for generations and never moved their animals.','The nomadic herders moved between seasonal pastures with their animals.','一处定居不迁徙不符合 nomadic 的游牧含义。'),[Q(1,'What did the nomadic herders follow?','Seasonal grasslands.','A fixed city address.','A nightly news broadcast.','nomadic.s1 指随季节迁移。'),Q(2,'Why did Mara choose one home base?','She was tired of moving among cities.','She wanted to move every week.','She had joined a herding group.','nomadic.s2 描述漂泊生活，她希望停止这种生活。'),Q(1,'Which lifestyle is nomadic?','Moving with animals between pastures.','Living in one permanent home without travel.','Attending the same meeting once a year.','随牲畜迁徙符合 nomadic。','meaning'),Q(2,'Nomadic can describe?','a person’s frequently changing, unsettled routine','a fixed address that never changes','a single loud sound','该词也可比喻漂泊不定的生活。','meaning')]);
P('nomadism','From nomad + -ism; nomad itself comes through Greek nomas “roaming for pasture,” and nomadism names a way of life involving movement with livestock or between temporary homes.',C('nomadism.s1','社会','The documentary examined nomadism in the region, showing how families moved with their herds between seasonal pastures.','纪录片研究当地的游牧生活，展示家庭如何随牲畜在季节性牧场间迁徙。','The documentary examined nomadism / in the region / showing how families moved / with their herds between seasonal pastures.','nomadism 指随牲畜迁徙或在临时住所之间移动的生活方式。','家庭按季节随牧群寻找草场。'),M('The documentary defined nomadism as permanent settlement in one place with no movement between pastures.','The documentary defined nomadism as seasonal movement with herds between pastures.','完全固定居住与游牧迁徙相反。'),[Q(1,'What did the families move with?','Their herds.','A newspaper press.','A group of nocturnal birds.','nomadism.s1 描述随牧群迁徙。'),Q(1,'Why did they change pastures?','They moved between seasonal grazing areas.','They never moved from one permanent farm.','They were nominated for an award.','例句说明按季节迁移牧场。','context'),Q(1,'Nomadism is a way of life involving?','movement between places, often with livestock','remaining permanently in one fixed location','working only during the night','nomadism 指迁徙生活方式。','meaning'),Q(1,'Which suffix turns nomad into a name for a practice or system?','-ism','-less','-ly','nomad + -ism forms nomadism.','word-formation')]);
P('nominal','From Latin nominalis “of a name,” from nomen “name”; it can mean existing in name only, very small or token in amount, or relating to a noun or name.',[C('nominal.s1','书面','The director was the nominal head of the committee, while the deputy made the daily decisions.','主任名义上是委员会负责人，但日常决策由副主任作出。','The director was the nominal head / of the committee / while the deputy / made the daily decisions.','nominal.s1 表示名义上的、实际上权力或作用很小的。','真正负责日常决策的是副主任。'),C('nominal.s2','商业','The museum charges a nominal fee of one dollar to cover the printed map and keep admission affordable.','博物馆收取一美元的象征性费用，用于支付地图印刷成本并保持门票价格亲民。','The museum charges a nominal fee / of one dollar / to cover the printed map / and keep admission affordable.','nominal.s2 指极小、象征性的金额。','一美元费用很低，主要是象征性收费。'),C('nominal.s3','语言','In the sentence “The bright red kite flew,” the phrase “the bright red kite” is a nominal group headed by the noun kite.','在句子“The bright red kite flew”中，短语“the bright red kite”是由名词kite作中心词的名词短语。','In the sentence / “The bright red kite flew” / the phrase “the bright red kite” / is headed by the noun kite.','nominal.s3 指与名词或名称有关的语言成分。','kite 是该名词短语的中心词。')],M('The deputy made every decision, but the report called the director the nominal head and said he held all real authority.','The report called the director the nominal head because the deputy made the daily decisions.','名义负责人不掌握实际决策权。'),[Q(1,'Who made the daily committee decisions?','The deputy.','The nominal director.','The museum visitors.','nominal.s1 表示主任只有名义头衔。'),Q(2,'How much was the museum’s nominal fee?','One dollar.','One hundred dollars.','Nothing, because the map was free.','nominal.s2 指很小的象征性收费。'),Q(3,'What is the head noun in “the bright red kite”?','kite','bright','the','nominal.s3 涉及名词短语和名词中心词。','grammar'),Q(2,'A nominal charge is usually?','a very small or token amount','the full market price in every case','a fee paid only in gold','nominal 可表示象征性、金额很小的。','meaning')]);
P('nominate','From Latin nominare “to name or call by name”; it means to formally suggest someone as a candidate or designate someone for a role or duty.',[C('nominate.s1','政治','The party will nominate a candidate for the district seat after local members finish their vote.','地方成员投票结束后，该党将为这个选区席位提名一名候选人。','The party will nominate a candidate / for the district seat / after local members / finish their vote.','nominate.s1 指正式提名某人参选职位或奖项。','候选人须先经地方成员投票确定。'),C('nominate.s2','正式','The board nominated Dr. Chen to lead the safety review and report its findings by June.','董事会任命陈博士负责安全审查，并要求她在六月前报告结果。','The board nominated Dr. Chen / to lead the safety review / and report its findings / by June.','nominate.s2 可指指定或任命某人承担工作。','董事会指定负责人履行职责。')],M('The committee nominated her for the award as the winner already, although it had only proposed her name for consideration.','The committee nominated her for the award, and the judges later selected the winner.','nominate 表示提名候选人，不等于已经获奖。','meaning'),[Q(1,'What will the party do after members vote?','Formally propose a candidate.','Announce the final vote count as a weather report.','Appoint every voter to the district seat.','nominate.s1 指提名候选人。'),Q(2,'What duty did the board give Dr. Chen?','Lead the safety review.','Run for the district seat.','Print the museum newsletter.','nominate.s2 指指定她承担工作。'),Q(1,'Does being nominated guarantee that someone wins an award?','No; nomination proposes a candidate for consideration.','Yes; nomination always means the person has already won.','Yes; nominees cannot be judged.','提名与最终获奖是不同步骤。','distinction'),Q(1,'Which pattern is natural?','nominate someone for an award','nominate someone an award for','nominate to someone an award','nominate someone for something 是常见搭配。','collocation')]);
P('nominee','From nominate + -ee; the suffix marks the person receiving the action, so a nominee is someone formally proposed for an award, election, or job, or appointed to act for another person.',[C('nominee.s1','通用','Each nominee for the science prize gave a short presentation before the judges announced the winner.','科学奖的每位候选人都作了简短陈述，随后评委宣布获奖者。','Each nominee for the science prize / gave a short presentation / before the judges / announced the winner.','nominee.s1 指被正式提名参加奖项、选举或职位竞争的人。','候选人先陈述，之后评委才选出获奖者。'),C('nominee.s2','通用','The company’s nominee signed the documents as its representative while the directors were overseas.','董事们在海外期间，公司的被指定代表以代表身份签署了文件。','The company’s nominee signed the documents / as its representative / while the directors / were overseas.','nominee.s2 可指受委托代表他人行事的人。','被指定者代公司签署文件。')],M('The judges had not yet selected a winner, but the announcer called every nominee the confirmed prize recipient.','The judges called each person a nominee until they selected the prize recipient.','被提名人尚未必获奖，提名身份不能等同最终获奖者。','distinction'),[Q(1,'What did each science-prize nominee do?','Give a short presentation.','Sign documents for a company overseas.','Select the judges.','nominee.s1 指奖项候选人。'),Q(2,'Why did the company’s nominee sign the documents?','The person acted as the company’s representative.','The person had won the science prize.','The directors had already returned.','nominee.s2 是受托代表。'),Q(1,'A nominee is a person who has been?','formally proposed or designated','automatically declared the winner','excluded from any selection process','nominee 指被提名或指定的人。','meaning'),Q(1,'The suffix -ee in nominee points to?','the person receiving the nomination','the person who makes every nomination','a place where nominees meet','-ee 常表示接受动作的人。','word-formation')]);
P('non-attendance','From non- + attendance; it means failure to be present at an event, class, or work.',C('non-attendance.s1','教育','The school contacted the family after repeated non-attendance at morning lessons and offered help with transport.','学生多次未参加早课后，学校联系了家长，并提出协助解决交通问题。','The school contacted the family / after repeated non-attendance at morning lessons / and offered help / with transport.','non-attendance 指没有出席活动、课程或工作。','学生缺席早课，学校跟进并提供帮助。'),M('The register recorded non-attendance at every lesson even though the student was present in class each morning.','The register recorded attendance because the student was present at every morning lesson.','non-attendance 表示缺席，与每天到课矛盾。'),[Q(1,'Why did the school contact the family?','The student repeatedly missed morning lessons.','The student won a science prize.','The school had no morning lessons.','non-attendance.s1 指反复缺课。'),Q(1,'What help did the school offer?','Help with transport.','A nomination for a newspaper award.','A nickel alloy.','学校提出协助交通问题。','context'),Q(1,'Which preposition is natural?','non-attendance at class','non-attendance class of','non-attendance to at class','通常说 non-attendance at an event or class。','collocation'),Q(1,'What does the prefix non- contribute?','absence or negation','a repeated action','a person receiving an action','non- 表示缺少或否定。','word-formation')]);

})();
